(() => {
  'use strict';

  const $ = id => document.getElementById(id);
  const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const opt = (value, label, selected = false) => `<option value="${esc(value)}" ${selected ? 'selected' : ''}>${esc(label)}</option>`;
  const state = {
    client: null, session: null, member: null, page: 'overview', authMode: 'signin',
    cohortId: null, courseId: null, moduleId: null, assessmentId: null,
    submissionId: null, sessionId: null, participantId: null, participantProfileId: null,
    generatedCode: null, generatedStaffInvite: null, peopleTab: 'cohorts',
    filters: { programme: '', cohort: '', state: '', sort: 'count_desc' },
    peopleFilters: { search: '', programme: '', state: '', sort: 'name' },
    courseFilters: { search: '', sort: 'newest' }
  };

  const navigation = {
    admin: [['overview', 'Programme overview', 'overview'], ['people', 'People & access', 'people'], ['learning', 'Courses & modules', 'learning'], ['grading', 'Assignments', 'grading'], ['attendance', 'Live attendance', 'attendance'], ['reports', 'Reports', 'reports']],
    mentor: [['overview', 'Mentor overview', 'overview'], ['people', 'My mentees', 'people'], ['grading', 'Assignments', 'grading'], ['attendance', 'Live attendance', 'attendance'], ['reports', 'Reports', 'reports']],
    stakeholder: [['overview', 'Programme overview', 'overview'], ['reports', 'Reports', 'reports']],
    participant: [['learning', 'My learning', 'learning'], ['business', 'My business', 'business'], ['profile', 'My profile', 'people']]
  };
  const typeLabels = { video: 'Video lesson', reading: 'Reading', workbook: 'Workbook', multiple_choice: 'Multiple choice', checkboxes: 'Checkboxes', short_text: 'Short answer', long_text: 'Long answer', file_url: 'Assignment link' };

  function icon(name) {
    const paths = {
      overview: '<rect x="3" y="3" width="7" height="7"/><rect x="14" y="3" width="7" height="7"/><rect x="3" y="14" width="7" height="7"/><rect x="14" y="14" width="7" height="7"/>',
      people: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 1 3-3.87"/>',
      learning: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/>',
      attendance: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18M8 15l2 2 5-5"/>',
      reports: '<path d="M3 3v18h18"/><path d="M7 16l4-4 3 3 5-7"/>',
      grading: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>',
      business: '<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',
      plus: '<path d="M12 5v14M5 12h14"/>', lock: '<rect x="4" y="10" width="16" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3"/>',
      video: '<polygon points="5 3 19 12 5 21 5 3"/>', reading: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20V2H6.5A2.5 2.5 0 0 0 4 4.5z"/>',
      workbook: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/>',
      test: '<path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/>'
    };
    return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name] || paths.overview}</svg>`;
  }

  function toast(message) { const el = $('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 3800); }
  function initials(name) { return String(name || 'TC').split(/\s+/).filter(Boolean).slice(0, 2).map(v => v[0]).join('').toUpperCase(); }
  function dateLabel(value) { if (!value) return 'Not provided'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleDateString('en-MY', { day: 'numeric', month: 'short', year: 'numeric' }); }
  function money(value) { const amount = Number(value || 0); return `RM ${amount.toLocaleString('en-MY', { maximumFractionDigits: 0 })}`; }
  function head(title, description, eyebrow = 'PORTAL', actions = '') { return `<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(description)}</p></div>${actions ? `<div class="actions">${actions}</div>` : ''}</div>`; }
  function empty(title, description, iconName = 'overview') { return `<div class="empty-product">${icon(iconName)}<h2>${esc(title)}</h2><p>${esc(description)}</p></div>`; }
  function stat(label, value, note, tone = '') { return `<div class="stat ${tone}"><span class="label">${esc(label)}</span><strong>${esc(value)}</strong><small>${esc(note)}</small></div>`; }
  function modal(id, title, description, body, submit = 'Save') { return `<dialog id="${id}"><form id="${id}-form"><div class="modal-head"><div><h2>${esc(title)}</h2><p>${esc(description)}</p></div><button class="close-btn" type="button" data-close-dialog aria-label="Close">×</button></div><div class="modal-body">${body}<div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="secondary" type="button" data-close-dialog>Cancel</button><button class="primary" type="submit">${esc(submit)}</button></div></div></form></dialog>`; }
  function setFormError(form, message = '') { const box = form?.querySelector('.form-error'); if (!box) return false; box.textContent = message; box.hidden = !message; if (message) box.scrollIntoView({ block: 'nearest', behavior: 'smooth' }); return true; }
  async function rows(table, columns = '*', configure = q => q) { const { data, error } = await configure(state.client.from(table).select(columns)); if (error) throw error; return data || []; }
  async function count(table, configure = q => q) { const { count: total, error } = await configure(state.client.from(table).select('*', { count: 'exact', head: true })); if (error) throw error; return total || 0; }
  async function save(operation, message) { const { error } = await operation; if (error) throw error; toast(message); }
  function redirectUrl() { return `${location.origin}${location.pathname}`; }

  function applyRoute() {
    const query = new URLSearchParams(location.search);
    if (query.get('staffInvite')) { state.authMode = 'staff'; state.pendingInviteCode = query.get('staffInvite'); }
    const raw = location.hash.startsWith('#') ? location.hash.slice(1) : location.hash;
    if (!raw || raw.includes('access_token=') || raw.includes('error_description=')) return;
    const route = new URLSearchParams(raw);
    if (route.get('page')) state.page = route.get('page');
    state.cohortId = route.get('cohort') || null; state.courseId = route.get('course') || null;
    state.moduleId = route.get('module') || null; state.assessmentId = route.get('assessment') || null;
    state.submissionId = route.get('submission') || null; state.sessionId = route.get('session') || null;
    state.participantProfileId = route.get('participant') || null;
  }
  function syncRoute() {
    if (!state.member) return;
    const params = new URLSearchParams(); params.set('page', state.page);
    [['cohort', state.cohortId], ['course', state.courseId], ['module', state.moduleId], ['assessment', state.assessmentId], ['submission', state.submissionId], ['session', state.sessionId], ['participant', state.participantProfileId]].forEach(([key, value]) => { if (value) params.set(key, value); });
    const url = new URL(location.href); url.searchParams.delete('staffInvite'); url.hash = params.toString(); history.replaceState(null, '', url);
  }
  function resetDetails() { state.cohortId = null; state.courseId = null; state.moduleId = null; state.assessmentId = null; state.submissionId = null; state.sessionId = null; state.participantProfileId = null; state.generatedCode = null; state.generatedStaffInvite = null; }

  function renderLogin(message = '', type = '') {
    $('sidebar').hidden = true; document.querySelector('.shell').style.marginLeft = '0'; $('account-control').hidden = true;
    const signin = state.authMode === 'signin'; const participant = state.authMode === 'signup'; const staff = state.authMode === 'staff';
    $('content').innerHTML = `<div class="auth-layout"><section class="auth-card auth-wide"><div class="eyebrow">LEARNING & IMPACT PORTAL</div><h1>${signin ? 'Welcome back' : participant ? 'Join your cohort' : 'Accept staff invitation'}</h1><p>${signin ? 'Sign in to continue to your role-based workspace.' : participant ? 'Create a participant account using the private code supplied by your programme team.' : 'Mentors and stakeholders can register only with an invitation created by an administrator.'}</p><div class="auth-tabs three"><button type="button" data-auth-mode="signin" class="${signin ? 'active' : ''}">Sign in</button><button type="button" data-auth-mode="signup" class="${participant ? 'active' : ''}">Participant signup</button><button type="button" data-auth-mode="staff" class="${staff ? 'active' : ''}">Staff invitation</button></div>${signin ? `<form id="password-login"><label class="field">Email<input type="email" name="email" autocomplete="email" required></label><label class="field">Password<input type="password" name="password" autocomplete="current-password" required minlength="8"></label><button class="primary" type="submit">Sign in</button></form><details class="magic-details"><summary>Use a magic link instead</summary><form id="magic-login"><label class="field">Email<input type="email" name="email" required></label><button class="secondary" type="submit">Send magic link</button></form></details>` : participant ? `<form id="participant-signup"><div class="form-grid"><label class="field full">Cohort signup code<input name="signup_code" required autocomplete="off" placeholder="EKU-XXXXXXXXXXXX" style="text-transform:uppercase"><small>This determines which cohort you join.</small></label><label class="field full">Full name<input name="display_name" required minlength="2" autocomplete="name"></label><label class="field full">Email<input type="email" name="email" required autocomplete="email"></label><label class="field">Password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label class="field">Confirm password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label></div><button class="primary" type="submit">Create participant account</button></form>` : `<form id="staff-signup"><div class="form-grid"><label class="field full">Invitation code<input name="staff_invite_code" required value="${esc(state.pendingInviteCode || '')}" placeholder="STAFF-XXXXXXXXXXXXXXXX" style="text-transform:uppercase"></label><label class="field full">Invited email address<input type="email" name="email" required autocomplete="email"></label><label class="field">Password<input type="password" name="password" required minlength="8" autocomplete="new-password"></label><label class="field">Confirm password<input type="password" name="confirm_password" required minlength="8" autocomplete="new-password"></label></div><button class="primary" type="submit">Create staff account</button></form>`}<div id="login-message" class="login-message ${esc(type)}" role="alert">${esc(message)}</div></section></div>`;
  }

  function renderNoAccess() {
    $('sidebar').hidden = true; document.querySelector('.shell').style.marginLeft = '0'; $('account-control').hidden = false;
    const email = state.session?.user?.email || ''; $('account-name').textContent = email; $('account-avatar').textContent = initials(email);
    $('content').innerHTML = `<section class="card access-card"><div class="eyebrow">ACCESS PENDING</div><h1>Your account is not assigned to this portal</h1><p>Participants must register with a cohort code. Mentors and stakeholders must use an administrator-issued staff invitation.</p><div class="actions" style="justify-content:center"><button class="secondary" id="retry-access">Check access again</button><button class="secondary" id="pending-signout">Sign out</button></div></section>`;
  }

  function renderShell() {
    const nav = navigation[state.member.role] || [];
    if (state.page !== 'account' && !nav.some(v => v[0] === state.page)) state.page = nav[0]?.[0] || 'overview';
    $('sidebar').hidden = false; document.querySelector('.shell').style.marginLeft = ''; $('account-control').hidden = false;
    $('account-name').textContent = state.member.display_name; $('account-avatar').textContent = initials(state.member.display_name);
    $('nav').innerHTML = nav.map(([id, label, ico]) => `<button data-page="${id}" class="${state.page === id ? 'active' : ''}">${icon(ico)}${esc(label)}</button>`).join('');
    $('crumb').textContent = state.page === 'account' ? 'Account' : nav.find(v => v[0] === state.page)?.[1] || 'Portal';
  }

  function barChart(items, key, sort = 'count_desc') {
    const map = new Map(); items.forEach(item => { const value = item[key] || 'Not provided'; map.set(value, (map.get(value) || 0) + 1); });
    let values = [...map]; values.sort(sort === 'name' ? (a, b) => a[0].localeCompare(b[0]) : (a, b) => b[1] - a[1]);
    const max = Math.max(1, ...values.map(v => v[1]));
    return values.slice(0, 10).map(([label, value]) => `<div class="bar-row"><div class="bar-meta"><span>${esc(label)}</span><b>${value}</b></div><div class="progress"><i style="width:${Math.round(value / max * 100)}%"></i></div></div>`).join('');
  }

  function dashboardFilters(programmes, cohorts, participants) {
    const states = [...new Set(participants.map(v => v.state).filter(Boolean))].sort();
    return `<div class="filters dashboard-filters"><label>Programme<select data-dashboard-filter="programme"><option value="">All programmes</option>${programmes.map(v => opt(v.id, v.name, state.filters.programme === v.id)).join('')}</select></label><label>Cohort<select data-dashboard-filter="cohort"><option value="">All cohorts</option>${cohorts.filter(v => !state.filters.programme || v.programme_id === state.filters.programme).map(v => opt(v.id, v.name, state.filters.cohort === v.id)).join('')}</select></label><label>State<select data-dashboard-filter="state"><option value="">All states</option>${states.map(v => opt(v, v, state.filters.state === v)).join('')}</select></label><label>Chart sorting<select data-dashboard-filter="sort"><option value="count_desc" ${state.filters.sort === 'count_desc' ? 'selected' : ''}>Highest count first</option><option value="name" ${state.filters.sort === 'name' ? 'selected' : ''}>Alphabetical</option></select></label><button class="secondary btn-sm" id="reset-dashboard-filters">Reset filters</button></div>`;
  }

  async function overview() {
    const [participants, courses, modules, sessions, attendance, checkins, assignments, assessments, submissions, cohorts, programmes] = await Promise.all([
      rows('m_participants', 'id,cohort_id,state,gender,baseline_profit,onboarding_completed_at'), rows('m_courses', 'id,title,active'), rows('m_modules', 'id,course_id,published'), rows('m_attendance_sessions', 'id,cohort_id,finalized'), rows('m_attendance_records', 'session_id,participant_id,status'), rows('m_business_checkins', 'participant_id,reporting_month,sales,operating_costs,net_profit'), rows('m_module_assignments', 'participant_id,module_id'), rows('m_assessments', 'id,module_id,published'), rows('m_assessment_submissions', 'participant_id,assessment_id,status,passed'), rows('m_cohorts', 'id,programme_id,name,state'), rows('m_programmes', 'id,name')
    ]);
    const cohortMap = new Map(cohorts.map(v => [v.id, v]));
    const filtered = participants.filter(v => (!state.filters.programme || cohortMap.get(v.cohort_id)?.programme_id === state.filters.programme) && (!state.filters.cohort || v.cohort_id === state.filters.cohort) && (!state.filters.state || v.state === state.filters.state));
    const participantIds = new Set(filtered.map(v => v.id)); const cohortIds = new Set(filtered.map(v => v.cohort_id));
    const filteredAttendance = attendance.filter(v => participantIds.has(v.participant_id)); const marked = filteredAttendance.filter(v => v.status !== 'unmarked'); const present = marked.filter(v => v.status === 'present').length; const attendanceRate = marked.length ? Math.round(present / marked.length * 100) : 0;
    const filteredAssignments = assignments.filter(v => participantIds.has(v.participant_id)); const assessmentModule = new Map(assessments.map(v => [v.id, v.module_id])); const passed = new Set(submissions.filter(v => v.passed && participantIds.has(v.participant_id)).map(v => `${v.participant_id}:${assessmentModule.get(v.assessment_id)}`)); const completion = filteredAssignments.length ? Math.round(filteredAssignments.filter(v => passed.has(`${v.participant_id}:${v.module_id}`)).length / filteredAssignments.length * 100) : 0;
    const latest = new Map(); checkins.filter(v => participantIds.has(v.participant_id)).sort((a, b) => String(a.reporting_month).localeCompare(String(b.reporting_month))).forEach(v => latest.set(v.participant_id, v));
    const currentProfit = [...latest.values()].map(v => Number(v.net_profit ?? (Number(v.sales) - Number(v.operating_costs)))); const avgProfit = currentProfit.length ? Math.round(currentProfit.reduce((a, b) => a + b, 0) / currentProfit.length) : 0;
    const baselines = filtered.map(v => Number(v.baseline_profit)).filter(Number.isFinite); const avgBaseline = baselines.length ? baselines.reduce((a, b) => a + b, 0) / baselines.length : 0; const incomeGrowth = avgBaseline ? Math.round((avgProfit - avgBaseline) / Math.abs(avgBaseline) * 100) : 0;
    const pending = submissions.filter(v => v.status === 'submitted' && participantIds.has(v.participant_id)).length;
    return `${head(state.member.role === 'mentor' ? 'Mentor overview' : 'Programme overview', 'Live programme participation, learning progress and business outcomes within your authorised scope.', `${state.member.role.toUpperCase()} WORKSPACE`)}${dashboardFilters(programmes, cohorts, participants)}<div class="stats stats-8">${stat('Participants', filtered.length, `${filtered.filter(v => v.onboarding_completed_at).length} completed profiles`, 'accent')}${stat('Active cohorts', cohortIds.size, 'Within selected scope')}${stat('Active courses', courses.filter(v => v.active).length, `${modules.filter(v => v.published).length} published modules`)}${stat('Learning completion', `${completion}%`, `${passed.size} passed module assessments`)}${stat('Attendance rate', `${attendanceRate}%`, `${present} present records`)}${stat('Average participant profit', money(avgProfit), 'Latest monthly submission')}${stat('Profit growth', `${incomeGrowth >= 0 ? '+' : ''}${incomeGrowth}%`, 'Versus participant baselines', incomeGrowth >= 0 ? 'positive-stat' : 'negative-stat')}${stat('Awaiting mentor grading', pending, 'Manual assignments')}</div><div class="grid-equal"><section class="card"><div class="card-head"><div><h2>Participants by state</h2><p>Demographic distribution for the current filter</p></div></div>${filtered.length ? barChart(filtered, 'state', state.filters.sort) : empty('No participant profiles', 'Adjust the filters or wait for enrolment.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Participants by gender</h2><p>Only supplied profile values are counted</p></div></div>${filtered.length ? barChart(filtered, 'gender', state.filters.sort) : empty('No demographic data', 'Participant profiles will populate this view.', 'people')}</section></div><section class="card impact-funnel"><div class="funnel"><div><span>Participants enrolled</span><strong>${filtered.length}</strong></div><div><span>Profiles completed</span><strong>${filtered.filter(v => v.onboarding_completed_at).length}</strong></div><div><span>Modules assigned</span><strong>${filteredAssignments.length}</strong></div><div><span>Modules passed</span><strong>${passed.size}</strong></div></div></section>`;
  }

  function participantTable(participants, mentors, editable) {
    const mentorMap = new Map(mentors.map(v => [v.user_id, v.display_name]));
    return `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Business</th><th>Profile</th><th>Mentor</th><th></th></tr></thead><tbody>${participants.map(v => `<tr data-participant="${v.id}"><td><strong>${esc(v.full_name)}</strong><small>${esc(v.email || v.state || '—')}</small></td><td>${esc(v.business_name || 'Not completed')}</td><td><span class="pill ${v.onboarding_completed_at ? '' : 'amber'}">${v.onboarding_completed_at ? 'Complete' : 'Needs setup'}</span></td><td>${editable ? `<select class="inline-select" data-mentor><option value="">Unassigned</option>${mentors.map(m => opt(m.user_id, m.display_name, m.user_id === v.mentor_user_id)).join('')}</select>` : esc(mentorMap.get(v.mentor_user_id) || 'Assigned to you')}</td><td><div class="actions"><button class="secondary btn-sm" data-open-participant="${v.id}">View profile</button>${editable ? '<button class="secondary btn-sm" data-save-mentor>Save mentor</button>' : ''}</div></td></tr>`).join('')}</tbody></table></div>`;
  }

  function staffTable(members) {
    const staff = members.filter(v => v.role !== 'participant');
    return `<div class="table-wrap"><table><thead><tr><th>Staff member</th><th>Role</th><th>Status</th><th></th></tr></thead><tbody>${staff.map(v => `<tr data-membership="${v.user_id}"><td><strong>${esc(v.display_name)}</strong></td><td><select class="inline-select" data-role>${['admin', 'mentor', 'stakeholder'].map(role => opt(role, role, role === v.role)).join('')}</select></td><td><label class="switch-label"><input data-active type="checkbox" ${v.active ? 'checked' : ''}> ${v.active ? 'Active' : 'Inactive'}</label></td><td><button class="secondary btn-sm" data-save-member>Save changes</button></td></tr>`).join('')}</tbody></table></div>`;
  }

  async function people() {
    if (state.participantProfileId) return participantProfile(state.participantProfileId);
    const participants = await rows('m_participants', 'id,user_id,cohort_id,mentor_user_id,full_name,business_name,email,state,onboarding_completed_at,active', q => q.order('full_name'));
    if (state.member.role !== 'admin') return `${head('My mentees', 'Participant profiles, businesses and progress assigned to you.', 'MENTOR WORKSPACE')}<section class="card">${participants.length ? participantTable(participants, [], false) : empty('No mentees assigned', 'An administrator can assign participants to you.', 'people')}</section>`;
    if (state.cohortId) return cohortWorkspace();
    const [members, cohorts, programmes, codes, invites] = await Promise.all([rows('m_memberships', 'user_id,display_name,role,active', q => q.order('display_name')), rows('m_cohorts', 'id,programme_id,name,state,starts_on,ends_on,active', q => q.order('name')), rows('m_programmes', 'id,name,active', q => q.order('name')), rows('m_signup_codes', 'id,cohort_id,code_hint,expires_at,max_uses,used_count,active'), rows('m_staff_invites', 'id,email,display_name,role,code_hint,expires_at,accepted_at,created_at', q => q.order('created_at', { ascending: false }))]);
    const programmeMap = new Map(programmes.map(v => [v.id, v.name])); const mentorMap = new Map(members.filter(v => v.role === 'mentor').map(v => [v.user_id, v.display_name]));
    const query = state.peopleFilters.search.toLowerCase();
    let visibleCohorts = cohorts.filter(v => (!query || `${v.name} ${v.state || ''} ${programmeMap.get(v.programme_id) || ''}`.toLowerCase().includes(query)) && (!state.peopleFilters.programme || v.programme_id === state.peopleFilters.programme) && (!state.peopleFilters.state || v.state === state.peopleFilters.state));
    visibleCohorts.sort(state.peopleFilters.sort === 'participants' ? (a, b) => participants.filter(v => v.cohort_id === b.id).length - participants.filter(v => v.cohort_id === a.id).length : (a, b) => a.name.localeCompare(b.name));
    const states = [...new Set(cohorts.map(v => v.state).filter(Boolean))].sort();
    const actions = `<button class="secondary" data-open="programme-modal">New programme</button><button class="secondary" data-open="cohort-modal">New cohort</button><button class="primary" data-open="staff-invite-modal">${icon('plus')} Invite mentor</button>`;
    const cohortCards = visibleCohorts.map(cohort => { const people = participants.filter(v => v.cohort_id === cohort.id); const mentors = [...new Set(people.map(v => v.mentor_user_id).filter(Boolean))]; const activeCodes = codes.filter(v => v.cohort_id === cohort.id && v.active && (!v.expires_at || new Date(v.expires_at) > new Date()) && (v.max_uses == null || v.used_count < v.max_uses)).length; return `<button class="cohort-card" data-open-cohort="${cohort.id}"><div><span class="pill">${esc(programmeMap.get(cohort.programme_id) || 'Programme')}</span><h2>${esc(cohort.name)}</h2><p>${esc(cohort.state || 'All locations')}</p></div><div class="cohort-metrics"><span><strong>${people.length}</strong> participants</span><span><strong>${mentors.length}</strong> mentors</span><span><strong>${activeCodes}</strong> active codes</span></div><small>${mentors.length ? mentors.map(id => mentorMap.get(id)).filter(Boolean).join(', ') : 'No mentor assigned yet'}</small></button>`; }).join('');
    const programmeForm = `<div class="form-grid"><label class="field full">Programme name<input name="name" required></label><label class="field full">Description<textarea name="description"></textarea></label></div>`;
    const cohortForm = `<div class="form-grid"><label class="field">Programme<select name="programme_id" required><option value="">Select programme</option>${programmes.map(v => opt(v.id, v.name)).join('')}</select></label><label class="field">Cohort name<input name="name" required></label><label class="field">State<input name="state"></label><label class="field">Start date<input type="date" name="starts_on"></label><label class="field">End date<input type="date" name="ends_on"></label></div>`;
    const staffForm = `<div class="form-grid"><label class="field full">Full name<input name="display_name" required></label><label class="field full">Email address<input type="email" name="email" required></label><label class="field">Portal role<select name="role"><option value="mentor">Mentor</option><option value="stakeholder">Stakeholder</option><option value="admin">Administrator</option></select></label><label class="field">Invitation expiry<input type="datetime-local" name="valid_until" required></label><p class="help-text full">The administrator creates a secure invitation. The staff member uses it to set their own password and receives the normal Supabase confirmation email.</p></div>`;
    const inviteResult = state.generatedStaffInvite ? `<dialog id="staff-invite-result"><div class="modal-head"><div><h2>Staff invitation created</h2><p>Share the invitation link only with ${esc(state.generatedStaffInvite.display_name)}.</p></div><button class="close-btn" type="button" data-close-dialog>×</button></div><div class="modal-body"><div class="generated-code"><code id="staff-invite-code">${esc(state.generatedStaffInvite.invitation_code)}</code><button class="secondary" id="copy-staff-invite">Copy invitation link</button></div><dl class="definition-list"><dt>Email</dt><dd>${esc(state.generatedStaffInvite.email)}</dd><dt>Role</dt><dd>${esc(state.generatedStaffInvite.invited_role)}</dd><dt>Expires</dt><dd>${esc(dateLabel(state.generatedStaffInvite.expires_at))}</dd></dl><div class="form-actions"><button class="primary" type="button" data-close-dialog>Done</button></div></div></dialog>` : '';
    return `${head('People & access', 'Manage cohorts, participant profiles, mentors and authorised staff.', 'ADMINISTRATION', actions)}<div class="segmented people-tabs"><button class="${state.peopleTab === 'cohorts' ? 'active' : ''}" data-people-tab="cohorts">Cohorts & participants</button><button class="${state.peopleTab === 'staff' ? 'active' : ''}" data-people-tab="staff">Staff access</button></div>${state.peopleTab === 'cohorts' ? `<div class="filters"><label>Search<input data-people-filter="search" value="${esc(state.peopleFilters.search)}" placeholder="Cohort, programme or state"></label><label>Programme<select data-people-filter="programme"><option value="">All programmes</option>${programmes.map(v => opt(v.id, v.name, state.peopleFilters.programme === v.id)).join('')}</select></label><label>State<select data-people-filter="state"><option value="">All states</option>${states.map(v => opt(v, v, state.peopleFilters.state === v)).join('')}</select></label><label>Sort<select data-people-filter="sort"><option value="name" ${state.peopleFilters.sort === 'name' ? 'selected' : ''}>Cohort name</option><option value="participants" ${state.peopleFilters.sort === 'participants' ? 'selected' : ''}>Most participants</option></select></label></div><section class="card"><div class="card-head"><div><h2>Cohorts</h2><p>Open a cohort to manage its participants and mentor coverage.</p></div><span class="pill">${visibleCohorts.length} shown</span></div>${visibleCohorts.length ? `<div class="cohort-grid">${cohortCards}</div>` : empty('No matching cohorts', 'Adjust the filters or create a new cohort.', 'people')}</section>` : `<section class="card section-gap"><div class="card-head"><div><h2>Portal staff</h2><p>Only administrators can issue staff invitations.</p></div><span class="pill">${members.filter(v => v.role !== 'participant').length} accounts</span></div>${members.some(v => v.role !== 'participant') ? staffTable(members) : empty('No staff accounts', 'Invite the first mentor or stakeholder.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Invitation history</h2><p>Accepted and outstanding staff invitations</p></div></div>${invites.length ? `<div class="table-wrap"><table><thead><tr><th>Invitee</th><th>Role</th><th>Code</th><th>Expiry</th><th>Status</th></tr></thead><tbody>${invites.map(v => `<tr><td><strong>${esc(v.display_name)}</strong><small>${esc(v.email)}</small></td><td>${esc(v.role)}</td><td>•••• ${esc(v.code_hint)}</td><td>${esc(dateLabel(v.expires_at))}</td><td><span class="pill ${v.accepted_at ? '' : new Date(v.expires_at) < new Date() ? 'gray' : 'amber'}">${v.accepted_at ? 'Accepted' : new Date(v.expires_at) < new Date() ? 'Expired' : 'Pending'}</span></td></tr>`).join('')}</tbody></table></div>` : empty('No staff invitations', 'Use Invite mentor to create one.', 'people')}</section>`}${modal('programme-modal', 'New programme', 'Create a programme that contains one or more cohorts.', programmeForm, 'Create programme')}${modal('cohort-modal', 'New cohort', 'Create a participant cohort inside a programme.', cohortForm, 'Create cohort')}${modal('staff-invite-modal', 'Invite portal staff', 'Only an administrator can create this invitation.', staffForm, 'Create invitation')}${inviteResult}`;
  }

  async function cohortWorkspace() {
    const [cohorts, programmes, participants, members, codes, access] = await Promise.all([rows('m_cohorts', '*', q => q.eq('id', state.cohortId)), rows('m_programmes', 'id,name'), rows('m_participants', 'id,user_id,cohort_id,mentor_user_id,full_name,business_name,email,state,onboarding_completed_at,active', q => q.eq('cohort_id', state.cohortId).order('full_name')), rows('m_memberships', 'user_id,display_name,role,active', q => q.order('display_name')), rows('m_signup_codes', 'id,cohort_id,code_hint,expires_at,max_uses,used_count,active,created_at', q => q.eq('cohort_id', state.cohortId).order('created_at', { ascending: false })), rows('m_cohort_access', 'user_id,cohort_id', q => q.eq('cohort_id', state.cohortId))]);
    const cohort = cohorts[0]; if (!cohort) { state.cohortId = null; throw new Error('Cohort not found.'); }
    const programmeMap = new Map(programmes.map(v => [v.id, v.name])); const mentors = members.filter(v => v.role === 'mentor' && v.active); const staff = members.filter(v => ['mentor', 'stakeholder'].includes(v.role) && v.active); const memberMap = new Map(members.map(v => [v.user_id, v])); const assigned = access.map(v => memberMap.get(v.user_id)).filter(Boolean); const assignedMentors = new Set(participants.map(v => v.mentor_user_id).filter(Boolean)); const uncovered = participants.filter(v => !v.mentor_user_id).length;
    const actions = `<button class="secondary" id="back-cohorts">Back to cohorts</button><button class="secondary" data-open="cohort-access-modal">Staff visibility</button><button class="primary" data-open="signup-code-modal">${icon('plus')} Generate signup code</button>`;
    const codeForm = `<div class="form-grid"><input type="hidden" name="cohort_id" value="${cohort.id}"><label class="field">Expiry date and time<input type="datetime-local" name="valid_until" required></label><label class="field">Maximum signups<input type="number" name="allowed_uses" min="1" value="100" required></label><p class="help-text full">The full code is shown once. Course access for this cohort is controlled inside each course workspace.</p></div>`;
    const accessForm = `<div class="form-grid"><label class="field full">Mentor or stakeholder<select name="user_id" required><option value="">Select staff account</option>${staff.map(v => opt(v.user_id, `${v.display_name} · ${v.role}`)).join('')}</select></label><input type="hidden" name="cohort_id" value="${cohort.id}"></div>`;
    const result = state.generatedCode ? `<dialog id="generated-code-modal"><div class="modal-head"><div><h2>Signup code created</h2><p>Share this code only with the intended participants.</p></div><button class="close-btn" type="button" data-close-dialog>×</button></div><div class="modal-body"><div class="generated-code"><code id="generated-code-value">${esc(state.generatedCode.signup_code)}</code><button class="secondary" id="copy-generated-code">Copy code</button></div><dl class="definition-list"><dt>Cohort</dt><dd>${esc(cohort.name)}</dd><dt>Expires</dt><dd>${esc(dateLabel(state.generatedCode.expires_at))}</dd><dt>Maximum signups</dt><dd>${esc(state.generatedCode.max_uses ?? 'Unlimited')}</dd></dl><div class="form-actions"><button class="primary" type="button" data-close-dialog>Done</button></div></div></dialog>` : '';
    return `${head(cohort.name, `${programmeMap.get(cohort.programme_id) || 'Programme'} · ${cohort.state || 'All locations'}`, 'COHORT WORKSPACE', actions)}<div class="stats compact-stats">${stat('Participants', participants.length, 'Registered in this cohort')}${stat('Completed profiles', participants.filter(v => v.onboarding_completed_at).length, 'Business baseline supplied')}${stat('Assigned mentors', assignedMentors.size, `${uncovered} participants unassigned`)}${stat('Staff visibility', assigned.length, assigned.map(v => v.display_name).join(', ') || 'No additional staff')}</div><section class="card section-gap"><div class="card-head"><div><h2>Participants and mentor assignment</h2><p>Profiles appear automatically after cohort-code registration.</p></div></div>${participants.length ? participantTable(participants, mentors, true) : empty('Waiting for participant signups', 'Generate a code and share it with this cohort.', 'people')}</section><section class="card"><div class="card-head"><div><h2>Signup codes</h2><p>Only the last four characters remain visible after creation.</p></div></div>${codes.length ? `<div class="table-wrap"><table><thead><tr><th>Code</th><th>Usage</th><th>Expiry</th><th>Status</th></tr></thead><tbody>${codes.map(v => { const available = v.active && (!v.expires_at || new Date(v.expires_at) > new Date()) && (v.max_uses == null || v.used_count < v.max_uses); return `<tr><td><strong>•••• ${esc(v.code_hint)}</strong></td><td>${v.used_count} / ${v.max_uses ?? '∞'}</td><td>${esc(dateLabel(v.expires_at))}</td><td><span class="pill ${available ? '' : 'gray'}">${available ? 'Available' : 'Closed'}</span></td></tr>`; }).join('')}</tbody></table></div>` : empty('No signup codes yet', 'Generate the first private code for this cohort.', 'people')}</section>${modal('signup-code-modal', 'Generate cohort signup code', `New participants will automatically join ${cohort.name}.`, codeForm, 'Generate code')}${modal('cohort-access-modal', 'Grant staff visibility', 'Give a mentor or stakeholder visibility into this cohort.', accessForm, 'Grant access')}${result}`;
  }

  async function participantProfile(participantId = state.participantId) {
    const [profiles, cohorts, programmes, checkins, attendance, assignments, submissions] = await Promise.all([rows('m_participants', '*', q => q.eq('id', participantId)), rows('m_cohorts', 'id,programme_id,name,state'), rows('m_programmes', 'id,name'), rows('m_business_checkins', '*', q => q.eq('participant_id', participantId).order('reporting_month', { ascending: false })), rows('m_attendance_records', 'status,participant_id', q => q.eq('participant_id', participantId)), rows('m_module_assignments', 'module_id,participant_id', q => q.eq('participant_id', participantId)), rows('m_assessment_submissions', 'assessment_id,status,passed,final_score,participant_id', q => q.eq('participant_id', participantId))]);
    const profile = profiles[0]; if (!profile) throw new Error('Participant profile not found.');
    const cohort = cohorts.find(v => v.id === profile.cohort_id); const programme = programmes.find(v => v.id === cohort?.programme_id); const own = state.member.role === 'participant' && profile.user_id === state.session.user.id;
    let avatarUrl = ''; if (profile.avatar_path) { const { data } = await state.client.storage.from('m-participant-avatars').createSignedUrl(profile.avatar_path, 3600); avatarUrl = data?.signedUrl || ''; }
    const marked = attendance.filter(v => v.status !== 'unmarked'); const attendanceRate = marked.length ? Math.round(marked.filter(v => v.status === 'present').length / marked.length * 100) : 0; const passed = submissions.filter(v => v.passed).length; const latest = checkins[0]; const currentProfit = latest ? Number(latest.net_profit ?? Number(latest.sales) - Number(latest.operating_costs)) : 0; const baseline = Number(profile.baseline_profit || 0); const growth = baseline ? Math.round((currentProfit - baseline) / Math.abs(baseline) * 100) : 0;
    if (own) {
      const mandatory = !profile.onboarding_completed_at;
      const form = `<form id="business-profile-form" class="card profile-form"><div class="profile-form-intro"><div class="profile-photo large">${avatarUrl ? `<img src="${esc(avatarUrl)}" alt="${esc(profile.full_name)}">` : icon('people')}</div><div><span class="pill ${mandatory ? 'amber' : ''}">${mandatory ? 'Required setup' : 'Profile active'}</span><h2>${mandatory ? 'Tell us about your business' : 'Update your business profile'}</h2><p>${mandatory ? 'Complete this once before entering your learning workspace.' : 'Keep your programme and baseline information accurate.'}</p></div></div><div class="form-grid"><label class="field full">Profile photo<input type="file" name="avatar_file" accept="image/jpeg,image/png,image/webp"><small>Optional · JPG, PNG or WebP · maximum 3 MB</small></label><label class="field">Business name<input name="business_name" value="${esc(profile.business_name || '')}" required></label><label class="field">Business sector<input name="sector" value="${esc(profile.sector || '')}" required placeholder="Food, fashion, services..."></label><label class="field full">Business description<textarea name="business_description" required minlength="10" placeholder="What do you sell, who are your customers and how does the business operate?">${esc(profile.business_description || '')}</textarea></label><label class="field">Business start date<input type="date" name="business_started_on" value="${esc(profile.business_started_on || '')}"></label><label class="field">Registration status<select name="registration_status"><option value="">Select status</option>${['Not registered', 'SSM registered', 'Other registration'].map(v => opt(v, v, profile.registration_status === v)).join('')}</select></label><label class="field">Number of employees<input type="number" name="employee_count" min="0" value="${esc(profile.employee_count ?? '')}"></label><label class="field">Phone number<input name="phone" value="${esc(profile.phone || '')}"></label><label class="field">State<input name="state" value="${esc(profile.state || '')}" required></label><label class="field">Gender<select name="gender"><option value="">Prefer not to say</option>${['Female', 'Male', 'Non-binary', 'Other'].map(v => opt(v, v, profile.gender === v)).join('')}</select></label><label class="field">Age<input type="number" name="age" min="15" max="100" value="${esc(profile.age ?? '')}"></label><label class="field">Baseline month<input type="month" name="baseline_month" value="${esc(profile.baseline_month ? String(profile.baseline_month).slice(0, 7) : '')}" required></label><label class="field">Baseline monthly sales (RM)<input type="number" name="baseline_sales" min="0" step="0.01" value="${esc(profile.baseline_sales ?? '')}" required></label><label class="field">Baseline monthly costs (RM)<input type="number" name="baseline_costs" min="0" step="0.01" value="${esc(profile.baseline_operating_costs ?? '')}" required></label><label class="field">Baseline monthly profit (RM)<input type="number" name="baseline_profit" step="0.01" value="${esc(profile.baseline_profit ?? '')}" required><small>Profit may be negative.</small></label><label class="field full">Business goal<textarea name="goal" placeholder="What would you like to achieve through the programme?">${esc(profile.goal || '')}</textarea></label></div><div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary" type="submit">${mandatory ? 'Complete profile and continue' : 'Save profile changes'}</button></div></form>`;
      return `${head(mandatory ? 'Complete your profile' : 'My profile', mandatory ? 'Your business baseline helps the programme measure real progress.' : 'Your participant and business information.', 'PARTICIPANT PROFILE')}${mandatory ? '<section class="notice amber">Business onboarding is required before courses and monthly monitoring are unlocked.</section>' : ''}${form}`;
    }
    const back = state.member.role === 'admin' ? (state.cohortId ? 'Back to cohort' : 'Back to people') : 'Back to mentees';
    return `${head(profile.full_name, `${programme?.name || 'Programme'} · ${cohort?.name || 'Cohort'}`, 'PARTICIPANT PROFILE', `<button class="secondary" id="back-participant-profile">${back}</button>`)}<section class="card profile-overview"><div class="profile-hero"><div class="profile-photo">${avatarUrl ? `<img src="${esc(avatarUrl)}" alt="${esc(profile.full_name)}">` : icon('people')}</div><div><span class="pill ${profile.onboarding_completed_at ? '' : 'amber'}">${profile.onboarding_completed_at ? 'Profile complete' : 'Onboarding incomplete'}</span><h2>${esc(profile.business_name || 'Business not provided')}</h2><p>${esc(profile.business_description || 'No business description has been submitted.')}</p></div></div><div class="stats compact-stats">${stat('Baseline profit', money(profile.baseline_profit), profile.baseline_month ? dateLabel(profile.baseline_month) : 'No baseline month')}${stat('Latest monthly profit', money(currentProfit), latest ? dateLabel(latest.reporting_month) : 'No monthly submission')}${stat('Profit growth', `${growth >= 0 ? '+' : ''}${growth}%`, 'Compared with baseline')}${stat('Attendance', `${attendanceRate}%`, `${marked.length} marked classes`)}</div><div class="definition-grid"><div><dt>Sector</dt><dd>${esc(profile.sector || '—')}</dd></div><div><dt>State</dt><dd>${esc(profile.state || '—')}</dd></div><div><dt>Registration</dt><dd>${esc(profile.registration_status || '—')}</dd></div><div><dt>Employees</dt><dd>${esc(profile.employee_count ?? '—')}</dd></div><div><dt>Assigned modules</dt><dd>${assignments.length}</dd></div><div><dt>Passed assessments</dt><dd>${passed}</dd></div><div><dt>Business goal</dt><dd>${esc(profile.goal || '—')}</dd></div><div><dt>Contact</dt><dd>${esc(profile.email || profile.phone || '—')}</dd></div></div></section><section class="card"><div class="card-head"><div><h2>Monthly business performance</h2><p>Participant-published monitoring records</p></div></div>${checkins.length ? businessTable(checkins) : empty('No monthly updates', 'The participant has not published a monthly update yet.', 'business')}</section>`;
  }

  async function learning() { return state.member.role === 'admin' ? courseAdmin() : participantLearning(); }
  async function courseAdmin() {
    if (state.assessmentId) return assessmentBuilder(); if (state.courseId) return courseWorkspace();
    const [courses, modules, resources, assessments, access] = await Promise.all([rows('m_courses', '*', q => q.order('created_at', { ascending: false })), rows('m_modules', 'id,course_id,published'), rows('m_module_resources', 'id,module_id'), rows('m_assessments', 'id,module_id,published'), rows('m_course_cohort_access', 'course_id,cohort_id')]);
    let visible = courses.filter(v => !state.courseFilters.search || `${v.title} ${v.description || ''}`.toLowerCase().includes(state.courseFilters.search.toLowerCase()));
    visible.sort(state.courseFilters.sort === 'title' ? (a, b) => a.title.localeCompare(b.title) : state.courseFilters.sort === 'modules' ? (a, b) => modules.filter(v => v.course_id === b.id).length - modules.filter(v => v.course_id === a.id).length : (a, b) => String(b.created_at).localeCompare(String(a.created_at)));
    const courseForm = `<div class="form-grid"><label class="field full">Course title<input name="title" required></label><label class="field full">Description<textarea name="description" placeholder="Purpose, audience and expected outcomes"></textarea></label></div>`;
    const cards = visible.map(course => { const courseModules = modules.filter(v => v.course_id === course.id); const moduleIds = new Set(courseModules.map(v => v.id)); return `<button class="project-card" data-open-course="${course.id}"><div class="project-card-top"><span class="pill">Course workspace</span><span class="project-arrow">→</span></div><h2>${esc(course.title)}</h2><p>${esc(course.description || 'No course description yet.')}</p><div class="project-stats"><span><strong>${courseModules.length}</strong> modules</span><span><strong>${resources.filter(v => moduleIds.has(v.module_id)).length}</strong> learning items</span><span><strong>${assessments.filter(v => moduleIds.has(v.module_id)).length}</strong> assessments</span><span><strong>${access.filter(v => v.course_id === course.id).length}</strong> cohorts</span></div><small>Open workspace to manage the learning path and cohort access</small></button>`; }).join('');
    return `${head('Courses', 'Build structured learning journeys and grant access by cohort.', 'COURSE MANAGEMENT', `<button class="primary" data-open="course-modal">${icon('plus')} Create course</button>`)}<div class="filters"><label>Search courses<input data-course-filter="search" value="${esc(state.courseFilters.search)}" placeholder="Course title or description"></label><label>Sort by<select data-course-filter="sort"><option value="newest" ${state.courseFilters.sort === 'newest' ? 'selected' : ''}>Newest first</option><option value="title" ${state.courseFilters.sort === 'title' ? 'selected' : ''}>Course title</option><option value="modules" ${state.courseFilters.sort === 'modules' ? 'selected' : ''}>Most modules</option></select></label><span class="filter-summary">${visible.length} of ${courses.length} courses</span></div>${visible.length ? `<div class="project-grid">${cards}</div>` : `<section class="card">${empty('No matching courses', 'Create a course or adjust the search.', 'learning')}</section>`}${modal('course-modal', 'Create course workspace', 'Give the course a clear purpose. Modules and cohort access are managed inside it.', courseForm, 'Create course')}`;
  }

  function resourceItem(resource) { return `<div class="content-row"><span class="content-icon ${resource.kind}">${icon(resource.kind)}</span><div><strong>${esc(resource.title)}</strong><small>${esc(typeLabels[resource.kind] || resource.kind)}${resource.external_url ? ' · External link' : ' · Portal content'}</small></div><span class="pill gray">${resource.required ? 'Required' : 'Optional'}</span></div>`; }

  async function courseWorkspace() {
    const [courseRows, modules, resources, assessments, questions, cohorts, programmes, cohortAccess] = await Promise.all([rows('m_courses', '*', q => q.eq('id', state.courseId)), rows('m_modules', '*', q => q.eq('course_id', state.courseId).order('sequence_number')), rows('m_module_resources', '*', q => q.order('sequence_number')), rows('m_assessments', '*', q => q.order('sequence_number')), rows('m_assessment_questions', 'id,assessment_id'), rows('m_cohorts', 'id,programme_id,name,state', q => q.order('name')), rows('m_programmes', 'id,name'), rows('m_course_cohort_access', 'course_id,cohort_id,assigned_at', q => q.eq('course_id', state.courseId))]);
    const course = courseRows[0]; if (!course) { state.courseId = null; throw new Error('Course not found.'); }
    const moduleIds = new Set(modules.map(v => v.id)); const programmeMap = new Map(programmes.map(v => [v.id, v.name])); const accessIds = new Set(cohortAccess.map(v => v.cohort_id));
    const moduleForm = `<div class="form-grid"><input type="hidden" name="course_id" value="${course.id}"><label class="field">Module order<input type="number" name="sequence_number" min="1" value="${modules.length + 1}" required></label><label class="field">Pass mark (%)<input type="number" name="pass_mark" min="0" max="100" value="70" required></label><label class="field full">Module title<input name="title" required></label><label class="field full">Description<textarea name="description"></textarea></label><label class="field">Initial visibility<select name="published"><option value="false">Draft</option><option value="true">Published</option></select></label></div>`;
    const contentForm = `<input type="hidden" name="module_id"><div class="content-type-picker"><label><input type="radio" name="kind" value="video" checked><span>${icon('video')}<b>Video</b><small>YouTube, Vimeo or hosted link</small></span></label><label><input type="radio" name="kind" value="reading"><span>${icon('reading')}<b>Reading</b><small>Lesson text inside the portal</small></span></label><label><input type="radio" name="kind" value="workbook"><span>${icon('workbook')}<b>Workbook</b><small>Download or document link</small></span></label></div><div class="form-grid"><label class="field full">Item title<input name="title" required></label><label class="field full" data-content-text hidden>Lesson text<textarea name="content"></textarea></label><label class="field full" data-content-url>External URL<input type="url" name="external_url" placeholder="https://"></label><label class="field">Order<input type="number" name="sequence_number" min="1" value="1" required></label><label class="field checkbox-field"><input type="checkbox" name="required" value="true" checked> Required before assessment</label></div>`;
    const assessmentForm = `<input type="hidden" name="module_id"><div class="form-grid"><label class="field full">Assessment title<input name="title" required></label><label class="field full">Instructions<textarea name="description"></textarea></label><label class="field">Assessment order<input type="number" name="sequence_number" min="1" value="1" required></label><label class="field">Pass mark (%)<input type="number" name="pass_mark" min="0" max="100" value="70" required></label><label class="field">Grading approach<select name="grading_mode"><option value="automatic">Automatic quiz</option><option value="mentor">Mentor-graded assignment</option><option value="mixed">Mixed assessment</option></select></label><label class="field">Attempts allowed<select name="attempt_mode"><option value="once">One attempt only</option><option value="multiple">Multiple attempts</option></select></label><p class="help-text full">Participants must complete every required learning item and any earlier assessment before this opens.</p></div>`;
    const cohortForm = `<div class="form-grid"><label class="field full">Cohort<select name="cohort_id" required><option value="">Select cohort</option>${cohorts.filter(v => !accessIds.has(v.id)).map(v => opt(v.id, `${v.name} · ${programmeMap.get(v.programme_id) || 'Programme'}`)).join('')}</select></label><input type="hidden" name="course_id" value="${course.id}"><p class="help-text full">All current participants—and future participants who join this cohort—will receive the course automatically.</p></div>`;
    const moduleCards = modules.map(module => { const items = resources.filter(v => v.module_id === module.id); const tests = assessments.filter(v => v.module_id === module.id); return `<section class="module-workspace"><div class="module-workspace-head"><div class="module-title"><span class="module-index">${module.sequence_number}</span><div><div class="module-kicker">STEP ${module.sequence_number}</div><h2>${esc(module.title)}</h2><p>${esc(module.description || 'No module description.')}</p></div></div><div class="actions"><span class="pill ${module.published ? '' : 'amber'}">${module.published ? 'Published' : 'Draft'}</span><button class="secondary btn-sm" data-toggle-module="${module.id}" data-published="${module.published}">${module.published ? 'Unpublish' : 'Publish'}</button></div></div><div class="module-columns"><div><div class="subhead"><div><h3>Learning content</h3><small>Complete required items before assessment</small></div><button class="secondary btn-sm" data-add-content="${module.id}">+ Add item</button></div>${items.length ? `<div class="content-list">${items.map(resourceItem).join('')}</div>` : `<div class="mini-empty">No learning content yet.</div>`}</div><div><div class="subhead"><div><h3>Assessments</h3><small>Ordered tests and mentor-graded work</small></div><button class="secondary btn-sm" data-new-assessment="${module.id}" data-next-order="${tests.length + 1}">+ Create</button></div>${tests.length ? `<div class="assessment-list">${tests.map(test => `<button data-open-assessment="${test.id}"><span class="content-icon test">${icon('test')}</span><span><strong>${test.sequence_number}. ${esc(test.title)}</strong><small>${esc(test.grading_mode)} · ${test.max_attempts == null ? 'Multiple attempts' : 'One attempt'} · ${questions.filter(v => v.assessment_id === test.id).length} questions</small></span><span class="pill ${test.published ? '' : 'amber'}">${test.published ? 'Published' : 'Draft'}</span></button>`).join('')}</div>` : `<div class="mini-empty">No assessment yet.</div>`}</div></div></section>`; }).join('');
    const accessChips = cohortAccess.map(v => { const cohort = cohorts.find(c => c.id === v.cohort_id); return `<span class="access-chip"><span><b>${esc(cohort?.name || 'Cohort')}</b><small>${esc(programmeMap.get(cohort?.programme_id) || '')}</small></span><button data-remove-course-cohort="${v.cohort_id}" aria-label="Remove access">×</button></span>`; }).join('');
    const actions = `<button class="secondary" id="back-courses">Back to courses</button><button class="secondary" data-open="course-access-modal">Manage cohort access</button><button class="primary" data-open="module-modal">${icon('plus')} Add module</button>`;
    return `${head(course.title, course.description || 'Course project workspace', 'COURSE WORKSPACE', actions)}<div class="course-summary"><div><strong>${modules.length}</strong><span>Ordered modules</span></div><div><strong>${resources.filter(v => moduleIds.has(v.module_id)).length}</strong><span>Learning items</span></div><div><strong>${assessments.filter(v => moduleIds.has(v.module_id)).length}</strong><span>Assessments</span></div><div><strong>${cohortAccess.length}</strong><span>Cohorts with access</span></div></div><section class="card course-access-strip"><div><h2>Cohort access</h2><p>Participants receive this course through their cohort, not individual assignment.</p></div><div class="access-chips">${accessChips || '<span class="muted">No cohorts assigned yet.</span>'}</div></section>${modules.length ? moduleCards : `<section class="card">${empty('Add the first module', 'Modules create the required learning sequence.', 'learning')}</section>`}${modal('module-modal', 'Add module', `Build the next stage of ${course.title}.`, moduleForm, 'Add module')}${modal('content-modal', 'Add learning item', 'Choose the format and whether it is required before assessment.', contentForm, 'Add learning item')}${modal('assessment-modal', 'Create assessment', 'Set the order, grading method and attempt rule.', assessmentForm, 'Open assessment builder')}${modal('course-access-modal', 'Grant cohort access', 'Assign this complete learning journey to a cohort.', cohortForm, 'Grant access')}`;
  }

  async function assessmentBuilder() {
    const [assessmentRows, questions, keys] = await Promise.all([rows('m_assessments', '*', q => q.eq('id', state.assessmentId)), rows('m_assessment_questions', '*', q => q.eq('assessment_id', state.assessmentId).order('sequence_number')), rows('m_assessment_keys', '*')]);
    const assessment = assessmentRows[0]; if (!assessment) { state.assessmentId = null; throw new Error('Assessment not found.'); } const keyMap = new Map(keys.map(v => [v.question_id, v]));
    const questionForm = `<div class="form-grid"><label class="field">Question type<select name="question_type" id="question-type"><option value="multiple_choice">Multiple choice</option><option value="checkboxes">Checkboxes</option><option value="short_text">Short answer</option><option value="long_text">Long answer</option><option value="file_url">Assignment / file link</option></select></label><label class="field">Points<input type="number" name="points" min="0.5" step="0.5" value="1" required></label><label class="field full">Question or instruction<textarea name="prompt" required></textarea></label><div class="full" data-auto-question><label class="field">Answer choices, one per line<textarea name="options" placeholder="First choice&#10;Second choice&#10;Third choice"></textarea></label><label class="field">Correct choice number(s)<input name="correct_options" placeholder="1 for multiple choice, or 1,3 for checkboxes"><small>Use the choice numbers in the same order as above.</small></label><label class="field">Answer feedback<textarea name="explanation"></textarea></label></div><label class="field">Question order<input type="number" name="sequence_number" min="1" value="${questions.length + 1}" required></label><label class="field checkbox-field"><input type="checkbox" name="required" value="true" checked> Required question</label><p class="help-text full" data-manual-question hidden>This response will enter the assigned mentor's grading queue.</p></div>`;
    const cards = questions.map((question, index) => { const key = keyMap.get(question.id); const answer = key ? (Array.isArray(key.correct_answer) ? key.correct_answer.join(', ') : key.correct_answer) : 'Mentor graded'; return `<article class="question-card"><div class="question-number">${index + 1}</div><div><div class="question-meta"><span class="pill ${key ? 'blue' : 'amber'}">${esc(typeLabels[question.question_type] || question.question_type)}</span><span>${question.points} point${Number(question.points) === 1 ? '' : 's'}</span><span>${question.required ? 'Required' : 'Optional'}</span></div><h3>${esc(question.prompt)}</h3>${question.options ? `<div class="option-preview">${question.options.map((v, i) => `<span>${i + 1}. ${esc(v)}</span>`).join('')}</div>` : ''}<small>Answer: ${esc(answer)}</small></div><button class="danger btn-sm" data-delete-question="${question.id}">Remove</button></article>`; }).join('');
    const actions = `<button class="secondary" id="back-course-workspace">Back to course</button><button class="secondary" id="toggle-assessment" data-published="${assessment.published}">${assessment.published ? 'Unpublish' : 'Publish assessment'}</button><button class="primary" data-open="question-modal">${icon('plus')} Add question</button>`;
    return `${head(assessment.title, assessment.description || 'Build and publish the assessment.', 'ASSESSMENT BUILDER', actions)}<div class="builder-banner"><div><span class="pill ${assessment.published ? '' : 'amber'}">${assessment.published ? 'Published' : 'Draft'}</span><h2>${questions.length} questions · ${questions.reduce((sum, v) => sum + Number(v.points), 0)} total points</h2><p>Step ${assessment.sequence_number} · Pass mark ${assessment.pass_mark}% · ${assessment.max_attempts == null ? 'Multiple attempts' : 'One attempt only'} · ${esc(assessment.grading_mode)} grading</p></div><div class="builder-legend"><span><i class="auto-dot"></i> Automatic</span><span><i class="manual-dot"></i> Mentor review</span></div></div><section class="card"><div class="card-head"><div><h2>Questions</h2><p>Add as many response types as the assessment requires.</p></div></div>${questions.length ? `<div class="question-list">${cards}</div>` : empty('Add the first question', 'Use automatic or mentor-graded response types.', 'grading')}</section>${modal('question-modal', 'Add question', 'Choose how the participant should respond.', questionForm, 'Add question')}`;
  }

  async function participantLearning() {
    if (!state.participantId) { const profiles = await rows('m_participants', 'id', q => q.eq('user_id', state.session.user.id)); state.participantId = profiles[0]?.id || null; }
    if (state.assessmentId) return participantAssessment(); if (state.moduleId) return participantModule();
    const courses = await rows('m_courses', 'id,title,description', q => q.eq('active', true).order('title'));
    const paths = new Map(); for (const course of courses) { const { data, error } = await state.client.rpc('m_course_path', { target_course: course.id }); if (error) throw error; paths.set(course.id, data || []); }
    if (state.courseId) {
      const course = courses.find(v => v.id === state.courseId); if (!course) { state.courseId = null; throw new Error('This course is not assigned to your cohort.'); } const coursePath = paths.get(course.id) || [];
      return `${head(course.title, course.description || 'Complete each step in order to unlock the next.', 'MY COURSE', '<button class="secondary" id="back-my-courses">Back to my courses</button>')}<section class="learning-path">${coursePath.map((module, index) => { const total = Number(module.resource_count) + Number(module.assessment_count); const done = Number(module.completed_resource_count) + Number(module.passed_assessment_count); const progress = total ? Math.round(done / total * 100) : 0; return `<article class="path-step ${module.locked ? 'locked' : module.completed ? 'completed' : 'current'}"><div class="path-marker">${module.completed ? '✓' : module.locked ? icon('lock') : index + 1}</div><div class="card"><div class="card-head"><div><span class="pill ${module.locked ? 'gray' : module.completed ? '' : 'blue'}">${module.locked ? 'Locked' : module.completed ? 'Completed' : 'Available now'}</span><h2>${esc(module.title)}</h2><p>${esc(module.description || 'Learning module')}</p></div><strong>${progress}%</strong></div><div class="progress"><i style="width:${progress}%"></i></div><div class="module-state"><small>${done} of ${total} required items completed</small>${module.locked ? '<span class="muted">Complete the previous module first</span>' : `<button class="primary btn-sm" data-open-module="${module.module_id}">${module.completed ? 'Review module' : 'Continue module'}</button>`}</div></div></article>`; }).join('')}</section>`;
    }
    const cards = courses.map(course => { const path = paths.get(course.id) || []; if (!path.length) return ''; const completed = path.filter(v => v.completed).length; const percent = Math.round(completed / path.length * 100); return `<button class="project-card participant-course" data-open-course="${course.id}"><div class="project-card-top"><span class="pill">Assigned through cohort</span><span class="project-arrow">→</span></div><h2>${esc(course.title)}</h2><p>${esc(course.description || 'Your learning course')}</p><div class="progress"><i style="width:${percent}%"></i></div><div class="project-stats"><span><strong>${path.length}</strong> modules</span><span><strong>${completed}</strong> completed</span><span><strong>${percent}%</strong> progress</span></div><small>Continue the required learning sequence</small></button>`; }).join('');
    return `${head('My learning', 'Courses assigned to your cohort, with modules unlocked in sequence.', 'PARTICIPANT WORKSPACE')}${cards ? `<div class="project-grid">${cards}</div>` : `<section class="card">${empty('No course assigned yet', 'Your administrator grants course access to your cohort.', 'learning')}</section>`}`;
  }

  async function participantModule() {
    const [moduleRows, resources, notes, progress, assessments, submissions] = await Promise.all([rows('m_modules', '*', q => q.eq('id', state.moduleId)), rows('m_module_resources', '*', q => q.eq('module_id', state.moduleId).order('sequence_number')), rows('m_private_notes', '*', q => q.eq('participant_id', state.participantId)), rows('m_resource_progress', 'resource_id', q => q.eq('participant_id', state.participantId)), rows('m_assessments', '*', q => q.eq('module_id', state.moduleId).eq('published', true).order('sequence_number')), rows('m_assessment_submissions', '*', q => q.eq('participant_id', state.participantId).order('submitted_at', { ascending: false }))]);
    const module = moduleRows[0]; if (!module) throw new Error('This module is locked or unavailable.'); const noteMap = new Map(notes.map(v => [v.resource_id, v.note])); const done = new Set(progress.map(v => v.resource_id)); const requiredComplete = resources.filter(v => v.required).every(v => done.has(v.id));
    const sectionHtml = resources.map((resource, index) => `<section class="card lesson-section"><div class="lesson-order">${index + 1}</div><div class="card-head"><div><span class="pill ${resource.kind === 'video' ? 'blue' : ''}">${esc(typeLabels[resource.kind] || resource.kind)}</span><h2>${esc(resource.title)}</h2></div><span class="pill ${done.has(resource.id) ? '' : 'gray'}">${done.has(resource.id) ? 'Completed' : resource.required ? 'Required' : 'Optional'}</span></div>${resource.content ? `<div class="content-block">${esc(resource.content)}</div>` : ''}${resource.external_url ? `<a class="secondary" href="${esc(resource.external_url)}" target="_blank" rel="noopener">Open ${esc(typeLabels[resource.kind] || 'resource')}</a>` : ''}<div class="resource-action"><button class="secondary" data-studied="${resource.id}">${done.has(resource.id) ? 'Mark completed again' : 'Mark as completed'}</button></div><form class="note-form notes" data-resource="${resource.id}"><label class="field">My private notes<textarea name="note" placeholder="Notes are visible only to you">${esc(noteMap.get(resource.id) || '')}</textarea></label><div class="form-error" hidden></div><button class="secondary btn-sm" type="submit">Save notes</button></form></section>`).join('');
    let previousPassed = true;
    const assessmentHtml = assessments.map(assessment => { const attempts = submissions.filter(v => v.assessment_id === assessment.id); const latest = attempts[0]; const passed = attempts.some(v => v.passed); const locked = !requiredComplete || !previousPassed; const attemptLimitReached = assessment.max_attempts != null && attempts.length >= assessment.max_attempts; previousPassed = previousPassed && passed; return `<button class="assessment-entry ${locked || attemptLimitReached ? 'locked' : ''}" data-open-assessment="${assessment.id}" ${locked || attemptLimitReached ? 'disabled' : ''}><span class="content-icon test">${locked ? icon('lock') : icon('test')}</span><span><strong>${assessment.sequence_number}. ${esc(assessment.title)}</strong><small>${locked ? (!requiredComplete ? 'Complete every required learning item first' : 'Pass the previous assessment first') : latest ? (latest.status === 'graded' ? `Latest score ${latest.final_score}% · Attempt ${attempts.length}` : 'Submitted for mentor grading') : `${assessment.max_attempts == null ? 'Multiple attempts' : 'One attempt'} · Pass mark ${assessment.pass_mark}%`}</small></span><span class="pill ${locked ? 'gray' : latest?.status === 'submitted' ? 'amber' : passed ? '' : 'blue'}">${locked ? 'Locked' : attemptLimitReached ? 'Attempt used' : latest?.status === 'submitted' ? 'Awaiting review' : passed ? 'Passed' : 'Start'}</span></button>`; }).join('');
    return `${head(module.title, module.description || 'Complete required content before the assessment unlocks.', 'MY LEARNING', '<button class="secondary" id="back-modules">Back to course path</button>')}<div class="module-gate"><div><strong>${done.size}/${resources.filter(v => v.required).length}</strong><span>required learning items completed</span></div><span class="pill ${requiredComplete ? '' : 'amber'}">${requiredComplete ? 'Assessments unlocked' : 'Assessment locked'}</span></div><div class="lesson-stack">${sectionHtml || empty('No learning items', 'The administrator is still preparing this module.', 'learning')}${assessments.length ? `<section class="card"><div class="card-head"><div><h2>Assessments</h2><p>Tests open only after required content and earlier assessments are complete.</p></div></div><div class="assessment-list participant-list">${assessmentHtml}</div></section>` : ''}</div>`;
  }

  async function participantAssessment() {
    const [assessmentRows, questions, submissions] = await Promise.all([rows('m_assessments', '*', q => q.eq('id', state.assessmentId)), rows('m_assessment_questions', '*', q => q.eq('assessment_id', state.assessmentId).order('sequence_number')), rows('m_assessment_submissions', '*', q => q.eq('assessment_id', state.assessmentId).eq('participant_id', state.participantId).order('submitted_at', { ascending: false }))]);
    const assessment = assessmentRows[0]; if (!assessment) throw new Error('Assessment not found.'); const latest = submissions[0]; const remaining = assessment.max_attempts == null ? 'Multiple attempts allowed' : `${Math.max(0, assessment.max_attempts - submissions.length)} attempt remaining`;
    const fields = questions.map((question, index) => { let control = ''; if (question.question_type === 'multiple_choice') control = question.options.map(answer => `<label class="answer"><input type="radio" name="q_${question.id}" value="${esc(answer)}" ${question.required ? 'required' : ''}>${esc(answer)}</label>`).join(''); else if (question.question_type === 'checkboxes') control = question.options.map(answer => `<label class="answer"><input type="checkbox" name="q_${question.id}" value="${esc(answer)}">${esc(answer)}</label>`).join(''); else if (question.question_type === 'short_text') control = `<input class="assessment-input" name="q_${question.id}" ${question.required ? 'required' : ''}>`; else if (question.question_type === 'long_text') control = `<textarea class="assessment-input" name="q_${question.id}" ${question.required ? 'required' : ''}></textarea>`; else control = `<input class="assessment-input" type="url" name="q_${question.id}" placeholder="Paste a shareable file or document link" ${question.required ? 'required' : ''}>`; return `<fieldset class="participant-question" data-question-id="${question.id}" data-question-type="${question.question_type}"><legend><span>${index + 1}</span>${esc(question.prompt)} ${question.required ? '<b>*</b>' : ''}</legend><small>${esc(typeLabels[question.question_type])} · ${question.points} point${Number(question.points) === 1 ? '' : 's'}</small>${control}</fieldset>`; }).join('');
    const previous = latest ? `<div class="submission-status ${latest.status === 'submitted' ? 'pending' : latest.passed ? 'passed' : 'not-passed'}"><strong>${latest.status === 'submitted' ? 'Awaiting mentor grading' : `${latest.final_score}% · ${latest.passed ? 'Passed' : 'Not passed'}`}</strong><p>${esc(latest.feedback || (latest.status === 'submitted' ? 'Your assigned mentor has been notified.' : remaining))}</p></div>` : '';
    return `${head(assessment.title, `${assessment.description || 'Complete every required question.'} · ${remaining}`, 'ASSESSMENT', '<button class="secondary" id="back-assessment-module">Back to module</button>')}${previous}<form id="assessment-submit-form" class="card assessment-form" data-assessment="${assessment.id}">${fields || empty('No questions available', 'This assessment is not ready yet.', 'grading')}<div class="form-error" role="alert" hidden></div>${questions.length ? '<div class="form-actions"><button class="primary" type="submit">Submit assessment</button></div>' : ''}</form>`;
  }

  async function grading() {
    const [submissions, assessments, participants, notifications] = await Promise.all([rows('m_assessment_submissions', '*', q => q.order('submitted_at', { ascending: false })), rows('m_assessments', 'id,title,pass_mark,module_id'), rows('m_participants', 'id,full_name,business_name,mentor_user_id'), rows('m_notifications', '*', q => q.order('created_at', { ascending: false }))]);
    if (state.submissionId) return gradingDetail(submissions, assessments, participants, notifications);
    const assessmentMap = new Map(assessments.map(v => [v.id, v])); const participantMap = new Map(participants.map(v => [v.id, v])); const pending = submissions.filter(v => v.status === 'submitted'); const unread = notifications.filter(v => !v.read_at && v.kind === 'assignment_submitted').length;
    return `${head('Assignments', 'Review participant work that requires mentor judgement. Automatic tests bypass this queue.', 'GRADING WORKSPACE')}<div class="stats compact-stats">${stat('Awaiting grading', pending.length, 'Manual submissions')}${stat('Unread alerts', unread, 'Assignment notifications')}${stat('Graded submissions', submissions.filter(v => v.status === 'graded').length, 'Visible history')}${stat('Participants', new Set(submissions.map(v => v.participant_id)).size, 'With submissions')}</div><section class="card"><div class="card-head"><div><h2>Submission queue</h2><p>Newest work appears first.</p></div></div>${submissions.length ? `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Assessment</th><th>Submitted</th><th>Status</th><th></th></tr></thead><tbody>${submissions.map(v => { const participant = participantMap.get(v.participant_id); const assessment = assessmentMap.get(v.assessment_id); return `<tr><td><strong>${esc(participant?.full_name || 'Participant')}</strong><small>${esc(participant?.business_name || '')}</small></td><td>${esc(assessment?.title || 'Assessment')}</td><td>${esc(dateLabel(v.submitted_at))}</td><td><span class="pill ${v.status === 'submitted' ? 'amber' : v.passed ? '' : 'gray'}">${v.status === 'submitted' ? 'Needs grading' : `${v.final_score}%`}</span></td><td><button class="secondary btn-sm" data-open-submission="${v.id}">${v.status === 'submitted' ? 'Grade' : 'Review'}</button></td></tr>`; }).join('')}</tbody></table></div>` : empty('No submissions yet', 'Mentor-graded work will appear here automatically.', 'grading')}</section>`;
  }

  async function gradingDetail(submissions, assessments, participants, notifications) {
    const submission = submissions.find(v => v.id === state.submissionId); if (!submission) { state.submissionId = null; throw new Error('Submission not found.'); }
    const assessment = assessments.find(v => v.id === submission.assessment_id); const participant = participants.find(v => v.id === submission.participant_id); const questions = await rows('m_assessment_questions', '*', q => q.eq('assessment_id', submission.assessment_id).order('sequence_number'));
    const answers = questions.map((question, index) => { const value = submission.answers?.[question.id]; const shown = Array.isArray(value) ? value.join(', ') : value || 'No answer'; return `<article class="review-answer"><span>${index + 1}</span><div><small>${esc(typeLabels[question.question_type])}</small><h3>${esc(question.prompt)}</h3><div>${esc(shown)}</div></div></article>`; }).join('');
    const form = submission.status === 'submitted' ? `<form id="grade-submission-form" class="card grading-panel" data-submission="${submission.id}"><h2>Mentor grade</h2><p>Use a final percentage score across the full assignment.</p><div class="form-grid"><label class="field">Final score (%)<input type="number" name="grade_score" min="0" max="100" step="0.01" required></label><label class="field full">Feedback<textarea name="grade_feedback" required></textarea></label></div><div class="form-error" role="alert" hidden></div><div class="form-actions"><button class="primary" type="submit">Publish grade</button></div></form>` : `<section class="card grading-panel"><span class="pill">Graded</span><h2>${submission.final_score}% · ${submission.passed ? 'Passed' : 'Not passed'}</h2><p>${esc(submission.feedback || 'No feedback provided.')}</p></section>`;
    const related = notifications.filter(v => v.entity_id === submission.id && !v.read_at); if (related.length) state.client.from('m_notifications').update({ read_at: new Date().toISOString() }).in('id', related.map(v => v.id)).then(() => {});
    return `${head(assessment?.title || 'Assignment submission', `${participant?.full_name || 'Participant'} · Submitted ${dateLabel(submission.submitted_at)}`, 'SUBMISSION REVIEW', '<button class="secondary" id="back-grading">Back to queue</button>')}<div class="grading-layout"><section class="card"><div class="card-head"><div><h2>Participant responses</h2><p>Review each answer and any submitted link.</p></div></div><div class="review-list">${answers}</div></section>${form}</div>`;
  }

  function businessTable(records) { return `<div class="table-wrap"><table><thead><tr><th>Month</th><th>Sales</th><th>Costs</th><th>Net profit</th><th>Customers</th><th>Review</th></tr></thead><tbody>${records.map(v => `<tr><td>${esc(dateLabel(v.reporting_month))}</td><td>${money(v.sales)}</td><td>${money(v.operating_costs)}</td><td><strong>${money(v.net_profit ?? Number(v.sales) - Number(v.operating_costs))}</strong></td><td>${esc(v.customer_count ?? '—')}</td><td><span class="pill ${v.mentor_reviewed ? '' : 'gray'}">${v.mentor_reviewed ? 'Mentor reviewed' : 'Published'}</span></td></tr>`).join('')}</tbody></table></div>`; }
  async function business() {
    const [records, profiles] = await Promise.all([rows('m_business_checkins', '*', q => q.eq('participant_id', state.participantId).order('reporting_month', { ascending: false }).limit(24)), rows('m_participants', '*', q => q.eq('id', state.participantId))]); const profile = profiles[0];
    const latest = records[0]; const latestProfit = latest ? Number(latest.net_profit ?? Number(latest.sales) - Number(latest.operating_costs)) : 0; const baseline = Number(profile?.baseline_profit || 0); const growth = baseline ? Math.round((latestProfit - baseline) / Math.abs(baseline) * 100) : 0; const best = records.length ? Math.max(...records.map(v => Number(v.net_profit ?? Number(v.sales) - Number(v.operating_costs)))) : 0;
    const form = `<div class="form-grid"><label class="field">Reporting month<input type="month" name="reporting_month" required></label><label class="field">Sales / revenue (RM)<input type="number" name="sales" min="0" step="0.01" required></label><label class="field">Operating costs (RM)<input type="number" name="operating_costs" min="0" step="0.01" required></label><label class="field">Net profit (RM)<input type="number" name="net_profit" step="0.01" required><small>This may be negative.</small></label><label class="field">Customer count<input type="number" name="customer_count" min="0"></label><label class="field">Employees this month<input type="number" name="employee_count" min="0"></label><label class="field full">Notes and business changes<textarea name="notes" placeholder="New products, challenges, milestones or changes"></textarea></label><label class="field full">Impact story (optional)<textarea name="impact_story" placeholder="Share a success, learning or change resulting from the programme"></textarea></label><label class="field full checkbox-field"><input type="checkbox" name="story_consent" value="true"> I consent to this impact story being used in approved programme reporting.</label></div>`;
    const trend = records.slice().reverse().map(v => { const profit = Number(v.net_profit ?? Number(v.sales) - Number(v.operating_costs)); const max = Math.max(1, ...records.map(r => Math.abs(Number(r.net_profit ?? Number(r.sales) - Number(r.operating_costs))))); return `<div class="profit-bar"><span>${esc(String(v.reporting_month).slice(0, 7))}</span><div><i class="${profit < 0 ? 'negative' : ''}" style="height:${Math.max(4, Math.round(Math.abs(profit) / max * 100))}%"></i></div><b>${money(profit)}</b></div>`; }).join('');
    return `${head('My business', 'Publish monthly performance and track progress against your baseline.', 'BUSINESS MONITORING', '<button class="primary" data-open="business-checkin-modal">+ Publish monthly update</button>')}<div class="stats compact-stats">${stat('Baseline profit', money(baseline), profile?.baseline_month ? dateLabel(profile.baseline_month) : 'Profile baseline')}${stat('Latest profit', money(latestProfit), latest ? dateLabel(latest.reporting_month) : 'No update yet')}${stat('Profit growth', `${growth >= 0 ? '+' : ''}${growth}%`, 'Versus baseline')}${stat('Best recorded month', money(best), `${records.length} published months`)}</div>${records.length ? `<section class="card section-gap"><div class="card-head"><div><h2>Profit trend</h2><p>Monthly net profit published by you</p></div></div><div class="profit-chart">${trend}</div></section><section class="card"><div class="card-head"><div><h2>Monthly records</h2><p>You may update an existing month by publishing it again.</p></div></div>${businessTable(records)}</section>` : `<section class="card">${empty('Publish your first monthly update', 'Use your baseline as the starting point and add one record each month.', 'business')}</section>`}${modal('business-checkin-modal', 'Publish monthly business update', 'These figures feed your progress dashboard and authorised programme reports.', form, 'Publish update')}`;
  }

  async function attendance() {
    if (state.sessionId) return register(state.sessionId);
    const [sessions, cohorts] = await Promise.all([rows('m_attendance_sessions', '*', q => q.order('session_date', { ascending: false })), rows('m_cohorts', 'id,name,state', q => q.order('name'))]); const cohortMap = new Map(cohorts.map(v => [v.id, v.name]));
    const form = `<div class="form-grid"><label class="field">Cohort<select name="cohort_id" required><option value="">Select cohort</option>${cohorts.map(v => opt(v.id, v.name)).join('')}</select></label><label class="field">Meeting number<input type="number" name="meeting_number" min="1" required></label><label class="field full">Class title<input name="title" required></label><label class="field">Date<input type="date" name="session_date" required></label><label class="field">Start time<input type="time" name="starts_at"></label><label class="field">Delivery<select name="delivery_mode"><option value="physical">Physical</option><option value="zoom">Zoom</option><option value="teams">Microsoft Teams</option><option value="other">Other</option></select></label><label class="field">Location<input name="location"></label><label class="field full">Meeting link<input type="url" name="join_url" placeholder="https://"></label></div>`;
    return `${head('Live attendance', 'Select a cohort and mark each participant during the class.', 'ATTENDANCE', cohorts.length ? `<button class="primary" data-open="session-modal">${icon('plus')} New class register</button>` : '')}<section class="card">${sessions.length ? `<div class="table-wrap"><table><thead><tr><th>Date</th><th>Cohort</th><th>Session</th><th>Delivery</th><th>Status</th><th></th></tr></thead><tbody>${sessions.map(v => `<tr><td>${esc(v.session_date)}</td><td>${esc(cohortMap.get(v.cohort_id) || 'Cohort')}</td><td><strong>${esc(v.title)}</strong><small>Meeting ${v.meeting_number}</small></td><td>${esc(v.delivery_mode)}</td><td><span class="pill ${v.finalized ? '' : 'amber'}">${v.finalized ? 'Finalized' : 'Open'}</span></td><td><button class="secondary btn-sm" data-register="${v.id}">Open register</button></td></tr>`).join('')}</tbody></table></div>` : empty('No class registers', 'Create one when a live class is scheduled.', 'attendance')}</section>${modal('session-modal', 'New class register', 'The session can be physical or hosted externally.', form, 'Create register')}`;
  }
  async function register(id) {
    const sessions = await rows('m_attendance_sessions', '*', q => q.eq('id', id)); const session = sessions[0]; if (!session) throw new Error('Session not found.'); const [participants, records] = await Promise.all([rows('m_participants', 'id,full_name,business_name', q => q.eq('cohort_id', session.cohort_id).eq('active', true).order('full_name')), rows('m_attendance_records', 'participant_id,status', q => q.eq('session_id', id))]); const map = new Map(records.map(v => [v.participant_id, v.status])); const present = participants.filter(v => map.get(v.id) === 'present').length; const absent = participants.filter(v => map.get(v.id) === 'absent').length;
    return `${head(session.title, `${session.session_date} · Meeting ${session.meeting_number} · ${session.delivery_mode}`, 'CLASS REGISTER', `<button class="secondary" id="back-sessions">Back</button>${session.finalized ? '' : '<button class="primary" id="finalize-session">Finalize register</button>'}`)}<div class="attendance-summary"><div><strong>${present}</strong><span>Present</span></div><div><strong>${absent}</strong><span>Absent</span></div><div><strong>${participants.length - present - absent}</strong><span>Unmarked</span></div></div><section class="card">${participants.length ? `<div class="table-wrap"><table><thead><tr><th>Participant</th><th>Business</th><th>Attendance</th></tr></thead><tbody>${participants.map(v => { const status = map.get(v.id) || 'unmarked'; return `<tr><td><strong>${esc(v.full_name)}</strong></td><td>${esc(v.business_name || '—')}</td><td><div class="status-buttons" data-attendee="${v.id}">${['present', 'absent', 'unmarked'].map(s => `<button type="button" data-status="${s}" class="${status === s ? `selected-${s}` : ''}" ${session.finalized ? 'disabled' : ''}>${s}</button>`).join('')}</div></td></tr>`; }).join('')}</tbody></table></div>` : empty('No participants in this cohort', 'Cohort-code registrations will appear here.', 'people')}</section>`;
  }

  function account() { let ref = 'Configured project'; try { ref = new URL(window.PORTAL_CONFIG.supabaseUrl).hostname.split('.')[0]; } catch {} return `${head('Account', 'Profile and technical details are kept outside the programme dashboard.', 'ACCOUNT')}<div class="grid-equal"><section class="card"><div class="card-head"><div><h2>Portal identity</h2><p>Your account</p></div><span class="role-badge">${esc(state.member.role)}</span></div><dl class="definition-list"><dt>Name</dt><dd>${esc(state.member.display_name)}</dd><dt>Email</dt><dd>${esc(state.session.user.email)}</dd><dt>Role</dt><dd>${esc(state.member.role)}</dd><dt>Status</dt><dd>Active</dd></dl></section><section class="card"><div class="card-head"><div><h2>Email redirect configuration</h2><p>Use this exact production address in Supabase Auth settings</p></div><span class="pill">${location.protocol === 'https:' ? 'Production ready' : 'Local preview'}</span></div><div class="code-block">${esc(redirectUrl())}</div><p class="help-text">In Supabase → Authentication → URL Configuration, set the production Vercel address as the Site URL and add it to Redirect URLs. Confirmation links fall back to the Site URL if the address is not allowed.</p><dl class="definition-list"><dt>Database project</dt><dd>${esc(ref)}</dd><dt>Protection</dt><dd>Row Level Security</dd><dt>Namespace</dt><dd>m_</dd></dl></section></div>`; }
  function reports() { return `${head('Reports', 'Generate stakeholder-ready programme reports from approved records.', 'REPORTING')}<section class="card">${empty('Reports will populate from live records', 'Demographics, learning completion, attendance, income outcomes and approved stories will be consolidated here.', 'reports')}</section>`; }

  async function loadPage() {
    renderShell(); syncRoute(); $('account-menu').hidden = true; $('content').innerHTML = '<div class="loading-card">Loading live data…</div>';
    try { let html; if (state.page === 'overview') html = await overview(); else if (state.page === 'people') html = await people(); else if (state.page === 'learning') html = await learning(); else if (state.page === 'grading') html = await grading(); else if (state.page === 'attendance') html = await attendance(); else if (state.page === 'business') html = await business(); else if (state.page === 'profile') html = await participantProfile(state.participantId); else if (state.page === 'account') html = account(); else html = reports(); $('content').innerHTML = html; if (state.generatedCode && $('generated-code-modal')) $('generated-code-modal').showModal(); if (state.generatedStaffInvite && $('staff-invite-result')) $('staff-invite-result').showModal(); }
    catch (error) { console.error(error); $('content').innerHTML = `${head('Database upgrade required', 'One or more product tables or functions are unavailable.', 'ACTION REQUIRED')}<section class="notice amber">${esc(error.message)}</section>${empty('Run the latest database migration', 'Apply 004_product_workflows.sql and refresh this page.', 'overview')}`; }
  }
  async function loadMembership() {
    const { data, error } = await state.client.from('m_memberships').select('user_id,display_name,role,active').eq('user_id', state.session.user.id).eq('active', true).maybeSingle(); if (error) throw error; state.member = data; if (!data) return renderNoAccess();
    if (data.role === 'participant') { const profiles = await rows('m_participants', 'id,user_id,onboarding_completed_at', q => q.eq('user_id', state.session.user.id)); state.participantId = profiles[0]?.id || null; if (!profiles[0]?.onboarding_completed_at) { state.page = 'profile'; resetDetails(); } }
    await loadPage();
  }

  document.addEventListener('click', async event => {
    try {
      const authMode = event.target.closest('[data-auth-mode]'); if (authMode) { state.authMode = authMode.dataset.authMode; renderLogin(); return; }
      const page = event.target.closest('[data-page]'); if (page && state.member) { state.page = page.dataset.page; resetDetails(); await loadPage(); return; }
      if (event.target.closest('#account-trigger')) { $('account-menu').hidden = !$('account-menu').hidden; return; }
      if (event.target.closest('#sign-out') || event.target.closest('#pending-signout')) { await state.client.auth.signOut(); return; }
      if (event.target.closest('#retry-access')) { await loadMembership(); return; }
      const open = event.target.closest('[data-open]'); if (open) { $(open.dataset.open)?.showModal(); return; }
      const close = event.target.closest('[data-close-dialog]'); if (close) { close.closest('dialog').close(); return; }
      const peopleTab = event.target.closest('[data-people-tab]'); if (peopleTab) { state.peopleTab = peopleTab.dataset.peopleTab; await loadPage(); return; }
      const cohort = event.target.closest('[data-open-cohort]'); if (cohort) { state.cohortId = cohort.dataset.openCohort; await loadPage(); return; }
      if (event.target.closest('#back-cohorts')) { state.cohortId = null; state.generatedCode = null; await loadPage(); return; }
      const participant = event.target.closest('[data-open-participant]'); if (participant) { state.participantProfileId = participant.dataset.openParticipant; await loadPage(); return; }
      if (event.target.closest('#back-participant-profile')) { state.participantProfileId = null; await loadPage(); return; }
      const course = event.target.closest('[data-open-course]'); if (course) { state.courseId = course.dataset.openCourse; state.moduleId = null; await loadPage(); return; }
      if (event.target.closest('#back-courses')) { state.courseId = null; await loadPage(); return; }
      if (event.target.closest('#back-my-courses')) { state.courseId = null; await loadPage(); return; }
      const content = event.target.closest('[data-add-content]'); if (content) { $('content-modal').querySelector('[name=module_id]').value = content.dataset.addContent; $('content-modal').showModal(); return; }
      const newAssessment = event.target.closest('[data-new-assessment]'); if (newAssessment) { const dialog = $('assessment-modal'); dialog.querySelector('[name=module_id]').value = newAssessment.dataset.newAssessment; dialog.querySelector('[name=sequence_number]').value = newAssessment.dataset.nextOrder; dialog.showModal(); return; }
      const assessment = event.target.closest('[data-open-assessment]'); if (assessment && !assessment.disabled) { state.assessmentId = assessment.dataset.openAssessment; await loadPage(); return; }
      if (event.target.closest('#back-course-workspace')) { state.assessmentId = null; await loadPage(); return; }
      if (event.target.closest('#back-assessment-module')) { state.assessmentId = null; await loadPage(); return; }
      if (event.target.closest('#toggle-assessment')) { const button = event.target.closest('#toggle-assessment'); await save(state.client.from('m_assessments').update({ published: button.dataset.published !== 'true' }).eq('id', state.assessmentId), 'Assessment visibility updated.'); await loadPage(); return; }
      const deleteQuestion = event.target.closest('[data-delete-question]'); if (deleteQuestion) { if (window.confirm('Remove this question and its answer key?')) { await save(state.client.from('m_assessment_questions').delete().eq('id', deleteQuestion.dataset.deleteQuestion), 'Question removed.'); await loadPage(); } return; }
      const toggle = event.target.closest('[data-toggle-module]'); if (toggle) { await save(state.client.from('m_modules').update({ published: toggle.dataset.published !== 'true' }).eq('id', toggle.dataset.toggleModule), 'Module visibility updated.'); await loadPage(); return; }
      const removeAccess = event.target.closest('[data-remove-course-cohort]'); if (removeAccess) { if (window.confirm('Remove this course from the cohort? Participants will lose access.')) { await save(state.client.from('m_course_cohort_access').delete().eq('course_id', state.courseId).eq('cohort_id', removeAccess.dataset.removeCourseCohort), 'Cohort access removed.'); await loadPage(); } return; }
      const saveMember = event.target.closest('[data-save-member]'); if (saveMember) { const tr = saveMember.closest('[data-membership]'); await save(state.client.from('m_memberships').update({ role: tr.querySelector('[data-role]').value, active: tr.querySelector('[data-active]').checked }).eq('user_id', tr.dataset.membership), 'Staff access updated.'); await loadPage(); return; }
      const saveMentor = event.target.closest('[data-save-mentor]'); if (saveMentor) { const tr = saveMentor.closest('[data-participant]'); await save(state.client.from('m_participants').update({ mentor_user_id: tr.querySelector('[data-mentor]').value || null }).eq('id', tr.dataset.participant), 'Mentor assignment updated.'); await loadPage(); return; }
      if (event.target.closest('#copy-generated-code')) { await navigator.clipboard.writeText($('generated-code-value').textContent); event.target.textContent = 'Copied'; return; }
      if (event.target.closest('#copy-staff-invite')) { const code = $('staff-invite-code').textContent; await navigator.clipboard.writeText(`${location.origin}${location.pathname}?staffInvite=${encodeURIComponent(code)}`); event.target.textContent = 'Link copied'; return; }
      const registerButton = event.target.closest('[data-register]'); if (registerButton) { state.sessionId = registerButton.dataset.register; await loadPage(); return; }
      if (event.target.closest('#back-sessions')) { state.sessionId = null; await loadPage(); return; }
      if (event.target.closest('#finalize-session')) { await save(state.client.from('m_attendance_sessions').update({ finalized: true, finalized_at: new Date().toISOString() }).eq('id', state.sessionId), 'Register finalized.'); await loadPage(); return; }
      const status = event.target.closest('[data-status]'); if (status) { const participantId = status.closest('[data-attendee]').dataset.attendee; await save(state.client.from('m_attendance_records').upsert({ session_id: state.sessionId, participant_id: participantId, status: status.dataset.status, marked_by: state.session.user.id, marked_at: new Date().toISOString() }, { onConflict: 'session_id,participant_id' }), 'Attendance updated.'); await loadPage(); return; }
      const moduleButton = event.target.closest('[data-open-module]'); if (moduleButton) { state.moduleId = moduleButton.dataset.openModule; await loadPage(); return; }
      if (event.target.closest('#back-modules')) { state.moduleId = null; await loadPage(); return; }
      const studied = event.target.closest('[data-studied]'); if (studied) { await save(state.client.from('m_resource_progress').upsert({ participant_id: state.participantId, resource_id: studied.dataset.studied }, { onConflict: 'participant_id,resource_id' }), 'Learning item completed.'); await loadPage(); return; }
      const submission = event.target.closest('[data-open-submission]'); if (submission) { state.submissionId = submission.dataset.openSubmission; await loadPage(); return; }
      if (event.target.closest('#back-grading')) { state.submissionId = null; await loadPage(); return; }
      if (event.target.closest('#reset-dashboard-filters')) { state.filters = { programme: '', cohort: '', state: '', sort: 'count_desc' }; await loadPage(); }
    } catch (error) { console.error(error); const form = event.target.closest('form'); if (!setFormError(form, error.message || 'Action failed.')) toast(error.message || 'Action failed.'); }
  });

  document.addEventListener('input', event => {
    const people = event.target.dataset.peopleFilter; if (people === 'search') { state.peopleFilters.search = event.target.value; clearTimeout(state.filterTimer); state.filterTimer = setTimeout(() => loadPage(), 250); }
    const course = event.target.dataset.courseFilter; if (course === 'search') { state.courseFilters.search = event.target.value; clearTimeout(state.filterTimer); state.filterTimer = setTimeout(() => loadPage(), 250); }
  });
  document.addEventListener('change', async event => {
    if (event.target.name === 'kind' && event.target.closest('#content-modal-form')) { const reading = event.target.value === 'reading'; document.querySelector('[data-content-text]').hidden = !reading; document.querySelector('[data-content-url]').hidden = reading; }
    if (event.target.id === 'question-type') { const automatic = ['multiple_choice', 'checkboxes'].includes(event.target.value); document.querySelector('[data-auto-question]').hidden = !automatic; document.querySelector('[data-manual-question]').hidden = automatic; }
    if (event.target.dataset.dashboardFilter) { state.filters[event.target.dataset.dashboardFilter] = event.target.value; if (event.target.dataset.dashboardFilter === 'programme') state.filters.cohort = ''; await loadPage(); }
    if (event.target.dataset.peopleFilter && event.target.dataset.peopleFilter !== 'search') { state.peopleFilters[event.target.dataset.peopleFilter] = event.target.value; await loadPage(); }
    if (event.target.dataset.courseFilter && event.target.dataset.courseFilter !== 'search') { state.courseFilters[event.target.dataset.courseFilter] = event.target.value; await loadPage(); }
  });

  document.addEventListener('submit', async event => {
    event.preventDefault(); const form = event.target; const formData = new FormData(form); const data = Object.fromEntries(formData.entries()); const button = form.querySelector('[type=submit]'); setFormError(form, ''); if ($('login-message')) { $('login-message').textContent = ''; $('login-message').className = 'login-message'; } if (button) button.disabled = true;
    try {
      if (form.id === 'password-login') { const { error } = await state.client.auth.signInWithPassword({ email: data.email, password: data.password }); if (error) throw error; return; }
      if (form.id === 'magic-login') { const { error } = await state.client.auth.signInWithOtp({ email: data.email, options: { emailRedirectTo: redirectUrl() } }); if (error) throw error; $('login-message').textContent = 'Magic link sent. Check your email.'; $('login-message').className = 'login-message success'; return; }
      if (form.id === 'participant-signup') {
        if (data.password !== data.confirm_password) throw new Error('The passwords do not match.'); const code = String(data.signup_code).trim().toUpperCase(); const { data: valid, error: validationError } = await state.client.rpc('m_validate_signup_code', { raw_code: code }); if (validationError) throw validationError; if (!valid?.length) throw new Error('This cohort code is invalid, expired or has reached its signup limit.');
        const { data: authData, error } = await state.client.auth.signUp({ email: data.email, password: data.password, options: { emailRedirectTo: redirectUrl(), data: { signup_code: code, display_name: data.display_name.trim() } } }); if (error) throw error; if (!authData.session) { state.authMode = 'signin'; renderLogin(`Account created for ${valid[0].cohort_name}. Confirm your email, then sign in to complete your business profile.`, 'success'); } return;
      }
      if (form.id === 'staff-signup') {
        if (data.password !== data.confirm_password) throw new Error('The passwords do not match.'); const code = String(data.staff_invite_code).trim().toUpperCase(); const { data: valid, error: validationError } = await state.client.rpc('m_validate_staff_invite', { raw_code: code, target_email: data.email }); if (validationError) throw validationError; if (!valid?.length) throw new Error('This staff invitation is invalid, expired or belongs to another email.');
        const { data: authData, error } = await state.client.auth.signUp({ email: data.email, password: data.password, options: { emailRedirectTo: redirectUrl(), data: { staff_invite_code: code } } }); if (error) throw error; if (!authData.session) { state.authMode = 'signin'; renderLogin(`${valid[0].invited_role} account created. Confirm your email, then sign in.`, 'success'); } return;
      }
      if (form.id === 'programme-modal-form') await save(state.client.from('m_programmes').insert({ name: data.name, description: data.description || null }), 'Programme created.');
      else if (form.id === 'cohort-modal-form') await save(state.client.from('m_cohorts').insert({ programme_id: data.programme_id, name: data.name, state: data.state || null, starts_on: data.starts_on || null, ends_on: data.ends_on || null }), 'Cohort created.');
      else if (form.id === 'signup-code-modal-form') { const { data: result, error } = await state.client.rpc('m_create_signup_code', { target_cohort: data.cohort_id, valid_until: new Date(data.valid_until).toISOString(), allowed_uses: Number(data.allowed_uses) }); if (error) throw error; state.generatedCode = result?.[0]; if (!state.generatedCode) throw new Error('The signup code could not be generated.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'staff-invite-modal-form') { const { data: result, error } = await state.client.rpc('m_create_staff_invite', { target_email: data.email, target_display_name: data.display_name, target_role: data.role, valid_until: new Date(data.valid_until).toISOString() }); if (error) throw error; state.generatedStaffInvite = { ...result?.[0], email: data.email, display_name: data.display_name }; if (!state.generatedStaffInvite.invitation_code) throw new Error('The invitation could not be created.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'cohort-access-modal-form') await save(state.client.from('m_cohort_access').upsert({ user_id: data.user_id, cohort_id: data.cohort_id }, { onConflict: 'user_id,cohort_id' }), 'Staff visibility granted.');
      else if (form.id === 'course-modal-form') { const { data: created, error } = await state.client.from('m_courses').insert({ title: data.title, description: data.description || null, created_by: state.session.user.id }).select('id').single(); if (error) throw error; state.courseId = created.id; toast('Course workspace created.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'course-access-modal-form') await save(state.client.from('m_course_cohort_access').upsert({ course_id: data.course_id, cohort_id: data.cohort_id, assigned_by: state.session.user.id }, { onConflict: 'course_id,cohort_id' }), 'Course granted to the cohort.');
      else if (form.id === 'module-modal-form') await save(state.client.from('m_modules').insert({ course_id: data.course_id, title: data.title, description: data.description || null, sequence_number: Number(data.sequence_number), pass_mark: Number(data.pass_mark), published: data.published === 'true', created_by: state.session.user.id }), 'Module added.');
      else if (form.id === 'content-modal-form') { const kind = formData.get('kind'); if (kind === 'reading' && !data.content?.trim()) throw new Error('Add the reading text before saving.'); if (kind !== 'reading' && !data.external_url?.trim()) throw new Error(`Add the ${typeLabels[kind].toLowerCase()} URL before saving.`); await save(state.client.from('m_module_resources').insert({ module_id: data.module_id, title: data.title, kind, content: kind === 'reading' ? data.content.trim() : null, external_url: kind === 'reading' ? null : data.external_url.trim(), sequence_number: Number(data.sequence_number), required: formData.has('required') }), 'Learning item added.'); }
      else if (form.id === 'assessment-modal-form') { const { data: created, error } = await state.client.from('m_assessments').insert({ module_id: data.module_id, title: data.title, description: data.description || null, sequence_number: Number(data.sequence_number), pass_mark: Number(data.pass_mark), grading_mode: data.grading_mode, max_attempts: data.attempt_mode === 'multiple' ? null : 1, created_by: state.session.user.id }).select('id').single(); if (error) throw error; state.assessmentId = created.id; toast('Assessment created. Add the first question.'); form.closest('dialog')?.close(); await loadPage(); return; }
      else if (form.id === 'question-modal-form') {
        const automatic = ['multiple_choice', 'checkboxes'].includes(data.question_type); let options = null; let correctAnswer = null;
        if (automatic) { options = String(data.options || '').split(/\r?\n/).map(v => v.trim()).filter(Boolean); if (options.length < 2) throw new Error('Add at least two answer choices.'); const numbers = String(data.correct_options || '').split(',').map(v => Number(v.trim())).filter(Number.isInteger); if (!numbers.length || numbers.some(v => v < 1 || v > options.length)) throw new Error('Enter valid correct choice numbers.'); if (data.question_type === 'multiple_choice' && numbers.length !== 1) throw new Error('Multiple choice requires exactly one correct choice.'); correctAnswer = data.question_type === 'multiple_choice' ? options[numbers[0] - 1] : [...new Set(numbers)].sort((a, b) => a - b).map(v => options[v - 1]); }
        const { data: question, error } = await state.client.from('m_assessment_questions').insert({ assessment_id: state.assessmentId, prompt: data.prompt, question_type: data.question_type, options, required: formData.has('required'), points: Number(data.points), sequence_number: Number(data.sequence_number) }).select('id').single(); if (error) throw error; if (automatic) { const { error: keyError } = await state.client.from('m_assessment_keys').insert({ question_id: question.id, correct_answer: correctAnswer, explanation: data.explanation || null }); if (keyError) throw keyError; }
        const types = await rows('m_assessment_questions', 'question_type', q => q.eq('assessment_id', state.assessmentId)); const hasAuto = types.some(v => ['multiple_choice', 'checkboxes'].includes(v.question_type)); const hasManual = types.some(v => !['multiple_choice', 'checkboxes'].includes(v.question_type)); await state.client.from('m_assessments').update({ grading_mode: hasAuto && hasManual ? 'mixed' : hasManual ? 'mentor' : 'automatic' }).eq('id', state.assessmentId); toast('Question added.'); form.closest('dialog')?.close(); await loadPage(); return;
      }
      else if (form.id === 'business-profile-form') {
        let avatarPath = null; const avatar = form.querySelector('[name=avatar_file]').files[0]; if (avatar) { if (avatar.size > 3145728) throw new Error('Profile photo must be smaller than 3 MB.'); const safeName = avatar.name.replace(/[^a-zA-Z0-9._-]/g, '-'); avatarPath = `${state.session.user.id}/${Date.now()}-${safeName}`; const { error: uploadError } = await state.client.storage.from('m-participant-avatars').upload(avatarPath, avatar, { upsert: true, contentType: avatar.type }); if (uploadError) throw uploadError; }
        const { error } = await state.client.rpc('m_save_business_profile', { target_business_name: data.business_name, target_description: data.business_description, target_sector: data.sector, target_phone: data.phone || null, target_state: data.state, target_gender: data.gender || null, target_age: data.age ? Number(data.age) : null, target_goal: data.goal || null, target_baseline_month: `${data.baseline_month}-01`, target_baseline_sales: Number(data.baseline_sales), target_baseline_costs: Number(data.baseline_costs), target_baseline_profit: Number(data.baseline_profit), target_employee_count: data.employee_count ? Number(data.employee_count) : 0, target_business_started_on: data.business_started_on || null, target_registration_status: data.registration_status || null, target_avatar_path: avatarPath }); if (error) throw error; toast('Business profile saved.'); state.page = 'learning'; await loadMembership(); return;
      }
      else if (form.id === 'business-checkin-modal-form') { await save(state.client.from('m_business_checkins').upsert({ participant_id: state.participantId, reporting_month: `${data.reporting_month}-01`, sales: Number(data.sales), operating_costs: Number(data.operating_costs), net_profit: Number(data.net_profit), customer_count: data.customer_count ? Number(data.customer_count) : null, employee_count: data.employee_count ? Number(data.employee_count) : null, notes: data.notes || null, impact_story: data.impact_story || null, story_consent: formData.has('story_consent') }, { onConflict: 'participant_id,reporting_month' }), 'Monthly business update published.'); }
      else if (form.id === 'session-modal-form') await save(state.client.from('m_attendance_sessions').insert({ cohort_id: data.cohort_id, meeting_number: Number(data.meeting_number), session_date: data.session_date, starts_at: data.starts_at || null, title: data.title, delivery_mode: data.delivery_mode, join_url: data.join_url || null, location: data.location || null, created_by: state.session.user.id }), 'Class register created.');
      else if (form.classList.contains('note-form')) { await save(state.client.from('m_private_notes').upsert({ participant_id: state.participantId, resource_id: form.dataset.resource, note: data.note || '', updated_at: new Date().toISOString() }, { onConflict: 'participant_id,resource_id' }), 'Private notes saved.'); return; }
      else if (form.id === 'assessment-submit-form') { const answers = {}; form.querySelectorAll('[data-question-id]').forEach(fieldset => { const id = fieldset.dataset.questionId; const name = `q_${id}`; answers[id] = fieldset.dataset.questionType === 'checkboxes' ? formData.getAll(name) : formData.get(name); }); const { data: result, error } = await state.client.rpc('m_submit_assessment', { target_assessment: form.dataset.assessment, submitted_answers: answers }); if (error) throw error; toast(result.status === 'submitted' ? 'Assignment submitted to your mentor.' : `Assessment graded: ${result.final_score}%.`); await loadPage(); return; }
      else if (form.id === 'grade-submission-form') { const { data: result, error } = await state.client.rpc('m_grade_submission', { target_submission: form.dataset.submission, grade_score: Number(data.grade_score), grade_feedback: data.grade_feedback }); if (error) throw error; toast(`Grade published: ${result.final_score}%.`); await loadPage(); return; }
      else return;
      form.closest('dialog')?.close(); await loadPage();
    } catch (error) { console.error(error); const message = error.message || 'Action failed.'; if (!setFormError(form, message)) { const login = $('login-message'); if (login && ['password-login', 'magic-login', 'participant-signup', 'staff-signup'].includes(form.id)) { login.textContent = message; login.className = 'login-message error'; } else toast(message); } }
    finally { if (button) button.disabled = false; }
  });

  async function start() {
    applyRoute(); const cfg = window.PORTAL_CONFIG || {}; if (!cfg.supabaseUrl || !cfg.supabasePublishableKey) throw new Error('Supabase configuration missing.');
    state.client = window.supabase.createClient(cfg.supabaseUrl, cfg.supabasePublishableKey, { auth: { persistSession: true, autoRefreshToken: true, detectSessionInUrl: true } });
    const { data, error } = await state.client.auth.getSession(); if (error) return renderLogin(error.message, 'error'); state.session = data.session; if (!state.session) renderLogin(); else await loadMembership();
    state.client.auth.onAuthStateChange((event, session) => { if (['SIGNED_IN', 'SIGNED_OUT', 'USER_UPDATED'].includes(event)) { state.session = session; state.member = null; state.participantId = null; if (!session) { resetDetails(); state.authMode = 'signin'; renderLogin(); } else setTimeout(() => loadMembership().catch(error => renderLogin(error.message, 'error')), 0); } });
  }
  start().catch(error => { console.error(error); $('content').innerHTML = `<section class="card setup-card"><h1>Portal could not start</h1><p>${esc(error.message)}</p></section>`; });
})();
